(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,66133,e=>{"use strict";let t={id:"cia-memo-giap-thanh-1966",registryId:"Q007",isVerified:!1,transcriptionStatus:"unverified_paraphrase",title:"CIA Intelligence Memorandum: The Strategy Debate in Hanoi",authorOrSpeaker:"Directorate of Intelligence, Central Intelligence Agency",role:"Office of Current Intelligence, CIA",side:"washington",date:"July 18, 1966",classification:"TOP SECRET (Declassified 2004)",archiveSource:"CIA Freedom of Information Act Electronic Reading Room",archiveId:"CIA-RDP79T00826A001100010046-3 (Intelligence memorandum summary)",excerpt:"The July 18, 1966 CIA intelligence memorandum reported evidence of tactical debate within Hanoi’s leadership between General Nguyen Chi Thanh (who advocated aggressive, large-unit conventional engagements to blunt American combat forces) and Defense Minister Vo Nguyen Giap (who urged force preservation, prolonged attrition, and decentralized guerrilla tactics).",historicalContext:"Contemporaneous evidence that American intelligence detected genuine tactical and doctrinal fractures within Hanoi’s military hierarchy during the height of U.S. troop escalation.",whyItMatters:"Refutes the perception that Hanoi was monolithic; reveals the high-stakes debate between large-unit offensive warfare (which culminated in Tet) and protracted defensive conservation.",originalDocumentUrl:"https://www.cia.gov/readingroom/document/cia-rdp79t00826a001100010046-3"},a={id:"mccarthy-hanoi-1968",registryId:"Q008",isVerified:!1,transcriptionStatus:"unverified_paraphrase",title:'"Hanoi—1968" (Eyewitness Dispatch from North Vietnam)',authorOrSpeaker:"Mary McCarthy",role:"Author and Eyewitness Observer",side:"neutral",date:"May 23, 1968",classification:"Published Eyewitness Account",archiveSource:"The New York Review of Books, Vol. 10, No. 10",archiveId:"NYRB-1968-0523 (Journalistic report summary)",excerpt:"In her May 1968 eyewitness report from Hanoi, author Mary McCarthy described street-level life under American aerial bombardment, reporting individual precast concrete cylinder bomb shelters spaced along sidewalks and widespread evacuation of children and the elderly to rural villages, observing that bombardment reinforced civilian social mobilization and collective discipline rather than causing urban collapse.",historicalContext:"Mary McCarthy traveled to North Vietnam in early 1968 during Operation Rolling Thunder, documenting street-level civil defense, bomb shelters, and civilian resilience.",whyItMatters:"Provides a rare, contemporaneous Western eyewitness record of how aerial bombardment operated in practice: rather than coercing capitulation, it stimulated decentralized civil defense and collective endurance.",originalDocumentUrl:"https://www.nybooks.com/articles/1968/05/23/hanoi-1968/"},n={id:"paris-accords-treaty-1973",registryId:"Q010",isVerified:!0,transcriptionStatus:"source_transcription",title:"Agreement on Ending the War and Restoring Peace in Viet-Nam (Paris Accords)",authorOrSpeaker:"William P. Rogers, Nguyen Duy Trinh, Tran Van Lam, Nguyen Thi Binh",role:"Signatories representing USA, DRV (North Vietnam), RVN (South Vietnam), PRG (Viet Cong)",side:"international",date:"January 27, 1973",classification:"International Treaty",archiveSource:"United Nations Treaty Series, Vol. 935, No. 13295",archiveId:"UNTS Vol. 935, Chapter I, Article 1, p. 4",excerpt:"The United States and all other countries respect the independence, sovereignty, unity, and territorial integrity of Viet-Nam as recognized by the 1954 Geneva Agreements on Viet-Nam.",historicalContext:"The treaty required the complete withdrawal of all U.S. military personnel while permitting approximately 150,000–200,000 North Vietnamese Army (PAVN) troops to remain in place inside South Vietnam.",whyItMatters:'President Thieu viewed the treaty as a fatal compromise for South Vietnam, acquiescing only after Nixon secretly promised in personal letters that the U.S. would "respond with full force" if Hanoi violated the agreement—a commitment Congress soon rendered legally impossible via the Case-Church Amendment.',originalDocumentUrl:"https://treaties.un.org/doc/Publication/UNTS/Volume%20935/v935.pdf"},i={id:"ap-casualty-disclosure-1995",registryId:"Q011",isVerified:!1,transcriptionStatus:"unverified_paraphrase",title:'Associated Press Wire: "Vietnam Releases First Official War Casualty Figures"',authorOrSpeaker:"Associated Press Wire Service",role:"Journalistic Wire Archive",side:"neutral",date:"April 4, 1995",classification:"Published Press Wire",archiveSource:"The Virginian-Pilot / Associated Press Archives",archiveId:"AP-VP-1995-0404 (News wire report summary)",excerpt:"On April 4, 1995, an Associated Press wire reported the Vietnamese government’s release of comprehensive casualty statistics for the 1954–1975 war, disclosing that 1.1 million North Vietnamese and Viet Cong combatants were killed and 600,000 wounded, alongside civilian casualty estimates of approximately 2 million dead across Vietnam.",historicalContext:"On the eve of the 20th anniversary of the fall of Saigon, Hanoi officially published its internal casualty counts for the 1954–1975 conflict, revealing the massive demographic toll.",whyItMatters:"Documents the primary disclosure of North Vietnamese military fatalities while illustrating how even official civilian casualty tallies have been reported with competing ranges (2 million combined vs. 4 million total).",originalDocumentUrl:"https://apnews.com/"};var o=e.i(31454);let r=[{id:"french-indochina-dien-bien-phu",number:1,timeframe:"1945–1954",leadImageId:"ho-telegram-1946",title:"Dien Bien Phu and the end of French rule",subtitle:"America paid for most of France’s war in Indochina. In 1954 France lost it anyway.",summary:"After World War II, Ho Chi Minh declared Vietnam independent, but France wanted its colony back. As the Cold War spread to Asia, the United States went from watching to paying for most of France’s war. France lost at Dien Bien Phu in 1954, and the Geneva talks split Vietnam in two for what was meant to be a short time.",isLandmark:!0,layout:"layered",story:{beats:[{id:"independence",kicker:"1945–1946",headline:"Ho Chi Minh declares independence, and asks America for help",body:["On September 2, 1945, Ho Chi Minh proclaimed an independent Vietnam in Hanoi, quoting the American Declaration of Independence. France wanted its colony back, and by late 1946 the two were at war.","Ho wrote to President Truman more than once asking for support. Truman, focused on rebuilding France as a European ally, never answered."],visual:{kind:"quote",citationId:"Q001"}},{id:"cold-war",kicker:"1949–1954",headline:"China and Korea turn a colonial war into a Cold War front",body:["The communist victory in China in 1949 and the Korean War in 1950 changed how Washington saw Vietnam. Ho was no longer a nationalist fighting a colonial power; he was the leading edge of Soviet and Chinese expansion.","So the United States started paying for France’s war, without getting any say in how France fought it.[^c1-1]"],visual:{kind:"share",title:"By 1954, Americans were paying for most of France’s war",label:"United States",remainderLabel:"France",low:78,high:80,note:"Share of French war costs in 1954. U.S. aid totaled nearly $2 billion.",citationId:"c1-1"},checkId:"c1-q1"},{id:"siege",kicker:"November 1953 – May 1954",headline:"General Navarre builds a fortress in a valley",body:["French commander Henri Navarre wanted a decisive battle. He picked a remote valley near the Laos border, Dien Bien Phu, and dared the Viet Minh to attack it."],visual:{kind:"siege",question:"Why did a fortress built to win a battle become a trap?",instruction:"Scroll to follow the 55-day siege.",takeaway:"The French held the valley, but Giap held the hills around it. Once the guns closed the airstrip, the garrison could not be resupplied or rescued.",caption:"Schematic map. Positions are approximate and not to scale.",citationId:"c1-2",steps:[{date:"November 1953",headline:"A base with no road in",state:"valley",body:"About 10,800 French troops dug into a ring of strongpoints around an airstrip. There were no roads to French territory, so every bullet, meal and replacement had to come in by air."},{date:"Winter 1953–54",headline:"The hills nobody thought could hold guns",state:"guns",body:"French planners assumed heavy artillery could never be hauled through the jungle mountains. Giap mobilized over 250,000 civilian porters who took howitzers apart, carried them up the far side of the hills, and hid them in dug-in positions looking down on the valley.[^c1-2]"},{date:"March 13, 1954",headline:"The first strongpoints fall",state:"outposts",body:"Giap opened with a massed bombardment the French had said was impossible. The northern outposts, Beatrice and then Gabrielle, fell within days. The French artillery commander, unable to silence the guns, took his own life.[^c1-2]"},{date:"Late March – April 1954",headline:"Trenches close in and the airstrip dies",state:"ring",body:"Viet Minh soldiers dug trenches that crept closer to the French lines every night. Shelling closed the airstrip, so supplies could only be dropped by parachute, and many landed on the wrong side of the lines.[^c1-2]"},{date:"May 7, 1954",headline:"Fifty-five days",state:"fall",body:"With bunkers flooding in the monsoon rains, the central position was overrun on May 7, just as diplomats at Geneva turned to Indochina. The isolated southern outpost, Isabelle, fell the next day.[^c1-3]"}]},checkId:"c1-q2"},{id:"vulture",kicker:"April 1954",headline:"Eisenhower weighs an air strike",body:["As the siege tightened, France asked for American air strikes. Inside the Eisenhower administration, the request split the people around the president.[^c1-1]"],visual:{kind:"debate",question:"Should the U.S. bomb the hills around Dien Bien Phu?",sides:[{stance:"Strike",who:"Secretary of State John Foster Dulles, Admiral Arthur Radford",argument:"Carrier air strikes (Operation Vulture) could break the siege and keep Indochina from falling to communism."},{stance:"Not alone",who:"President Eisenhower, Army Chief of Staff Matthew Ridgway",argument:"Fresh from Korea, they would not act without British allies and approval from Congress."}],outcome:"Britain said no, congressional leaders said no, and the U.S. stayed out."},checkId:"c1-q3"},{id:"aftermath",imageId:"geneva-conference-1954",moreImageIds:["dien-bien-phu-wounded-1954"],kicker:"Summer 1954",headline:"France leaves and America steps in",body:["At Geneva, Vietnam was split at the 17th parallel, supposedly until nationwide elections in 1956. Washington decided not to rescue France, but to replace it."],visual:{kind:"consequence"}}]},landmarkMoment:{bannerTitle:"The siege of Dien Bien Phu",dateline:"March 13 – May 7, 1954",location:"Muong Thanh Valley Basin, Northwestern Vietnam",quote:"Navarre’s entrenched valley bastion was systematically overwhelmed by artillery assembled on surrounding heights, turning the French stronghold into an untenable siege position.",quoteSpeaker:"Bernard B. Fall",quoteContext:"Historical synthesis from Hell in a Very Small Place (1966)"},whatHappened:{narrative:["On September 2, 1945, in Hanoi’s Ba Dinh Square, Ho Chi Minh proclaimed the establishment of the Democratic Republic of Vietnam (DRV), quoting directly from the American Declaration of Independence. French colonial authorities, determined to reassert sovereignty after wartime Japanese occupation, launched a military campaign to regain control, driving Ho’s Viet Minh into the northern mountains and initiating the First Indochina War in late 1946.","Between 1945 and 1949, Washington largely viewed the conflict as a regional European colonial war. However, the communist victory in China in 1949 and the outbreak of the Korean War in 1950 fundamentally altered American strategic calculations. Reframing the Viet Minh not as nationalist insurgents but as the vanguard of Sino-Soviet expansion in Southeast Asia, President Truman authorized direct military aid. By 1954, the United States was underwriting roughly 78 to 80 percent of France’s war expenditures—having committed nearly $2 billion[^c1-1]—yet Washington exercised virtually no command authority over French battlefield strategy.","In late 1953, French Commander Henri Navarre established a fortified base in the remote valley basin of Dien Bien Phu. Navarre’s operational premise was that superior French airpower, armor, and artillery in the valley would lure the Viet Minh into open ground and destroy them. French planners assumed the surrounding ring of jungle-covered mountains was impassable to heavy enemy artillery. Instead, General Vo Nguyen Giap mobilized over 250,000 civilian porters to dismantle heavy howitzers and haul them up the reverse slopes of the mountains, concealing them in dug-in caves overlooking the French garrison.[^c1-2] After a 55-day siege in which French airstrips were severed, the fortress fell on May 7, 1954, on the eve of the Geneva Conference.[^c1-3]"],keyEvents:[{date:"Sept 2, 1945",title:"Ho Chi Minh declares independence",detail:"In Hanoi, Ho Chi Minh declares Vietnam independent and appeals to the Atlantic Charter."},{date:"Dec 19, 1946",title:"The First Indochina War begins",detail:"Fighting in Haiphong and Hanoi drives the Viet Minh back to bases in the northern mountains."},{date:"Jan–Feb 1950",title:"China and the Soviets back Hanoi",detail:"Moscow and Beijing recognize Ho’s government. Truman approves the first direct military aid for France."},{date:"Nov 1953",title:"Navarre builds a base at Dien Bien Phu",detail:"French paratroopers take the remote valley and start building a fortified base."},{date:"March 13 – May 7, 1954",title:"The siege and fall of Dien Bien Phu",detail:"Giap’s guns in the hills wreck the French airstrips and strongpoints, and the garrison surrenders."}]},washington:{keyActors:["Harry S. Truman","Dwight D. Eisenhower","Dean Acheson","John Foster Dulles"],strategicObjective:"Stop communism from spreading in Southeast Asia, and keep France, a NATO ally, strong enough to help rebuild Europe.",underlyingAssumptions:["Eisenhower argued that if Indochina fell to communism, Thailand, Burma, Malaya and Indonesia would follow, one after another.","Washington saw Ho Chi Minh as an agent of Moscow and Beijing more than as a nationalist.","American money could buy a French victory, so no U.S. troops would be needed."],internalDebates:["Secretary of State Dulles and Admiral Radford wanted carrier air strikes to save Dien Bien Phu, a plan called Operation Vulture.","Eisenhower and Army Chief of Staff Matthew Ridgway refused to act without Britain and Congress. Both remembered Korea."],homeFrontConstraints:["Post-Korean War exhaustion: strong public and congressional reluctance to commit American ground divisions to another land conflict in Asia.","McCarthyite domestic anti-communist pressure: political vulnerability to accusations that it had lost Southeast Asia, as Truman had been blamed for losing China."],primaryDocumentRef:"nsc-68-indochina"},hanoi:{keyActors:["Ho Chi Minh","Vo Nguyen Giap","Truong Chinh","Pham Van Dong"],strategicObjective:"Drive out the French, win recognition as an independent country and build a socialist Vietnam.",underlyingAssumptions:["A long people’s war would wear down France’s will to fight and drain its economy.","Chinese artillery, anti-aircraft guns and supplies, which arrived after 1950, could make up for France’s better weapons.","As French casualty lists grew, voters in Paris would turn against the war."],internalDebates:["At Dien Bien Phu, Chinese advisers urged a fast, all-out assault. Giap chose a slower siege.","Truong Chinh’s harsh early land reform in the areas the Viet Minh controlled caused tension inside the movement."],homeFrontConstraints:["Severe economic poverty and food scarcity while mobilizing a quarter-million civilian porters across trackless mountain trails under French aerial bombing.","Heavy material dependence on Chinese munitions and Soviet military supplies."],primaryDocumentRef:"ho-truman-1946"},causalChain:{decision:{actor:"President Eisenhower",action:"He refused to send bombers to save the French at Dien Bien Phu. Then he decided the United States would take France’s place in the south.",date:"May–July 1954"},assumption:{premise:"With France gone, Washington thought it could build a strong, independent, non-communist country in the south.",blindSpot:"Ho Chi Minh had just beaten a European army. Millions of Vietnamese saw him as the man who won their independence."},result:{immediate:"The Geneva Accords split Vietnam at the 17th parallel until elections, which were set for July 1956.",counterAction:"Washington set up the SEATO alliance and backed Ngo Dinh Diem to run the south."},unintendedConsequence:"The United States took on the job of propping up a new, untested government in Saigon, while the fight over who should rule Vietnam stayed unsettled.",nextDecision:"Would Diem and Washington allow the 1956 elections?"},interactiveModule:{id:"dien-bien-phu-map",type:"dien-bien-phu-map",title:"The trap at Dien Bien Phu",prompt:"Move through the siege to see why French commanders felt safe in the valley, and what happened once Giap’s guns in the hills could reach the airstrip."},primaryDocuments:[{id:"ho-truman-1946",registryId:"Q001",isVerified:!0,transcriptionStatus:"source_transcription",title:"Telegram from Ho Chi Minh to President Harry S. Truman",authorOrSpeaker:"Ho Chi Minh",role:"President, Provisional Government of the Democratic Republic of Vietnam",side:"hanoi",date:"February 28, 1946",classification:"Archival Diplomatic Cable (Unanswered)",archiveSource:"U.S. National Archives and Records Administration (NARA), Record Group 226",archiveId:"NARA RG 226, Entry 140, Box 39 / DocsTeach ID 595462",excerpt:"I therefore earnestly appeal to you personally and to the American people to interfere urgently in support of our independence and help making the negotiations more in keeping with the principles of the Atlantic and San Francisco charters.",historicalContext:"In the months immediately following World War II, Ho Chi Minh wrote multiple letters to President Truman appealing to the Atlantic Charter and American principles of national self-determination. Washington, prioritizing French cooperation in post-war European reconstruction and the emergent containment of the Soviet Union, never formally replied.",whyItMatters:"Demonstrates Hanoi’s early effort to cultivate American diplomatic recognition before the Cold War solidified into rigid ideological blocs in East Asia.",originalDocumentUrl:"https://docsteach.org/document/ho-chi-minh-to-truman/"},{id:"nsc-68-indochina",registryId:"Q002",isVerified:!0,transcriptionStatus:"source_transcription",title:"The Position of the United States with Respect to Indochina (NSC 64)",authorOrSpeaker:"National Security Council",role:"Policy Planning Staff, Executive Office of the President",side:"washington",date:"February 27, 1950",classification:"TOP SECRET (Declassified)",archiveSource:"Foreign Relations of the United States (FRUS), 1950, East Asia and the Pacific, Vol. VI",archiveId:"FRUS 1950, Vol. VI, Document 480, pp. 745–747, Conclusions Para 10",excerpt:"It is important to United States security interests that all practicable measures be taken to prevent further communist expansion in Southeast Asia. Indochina is a key area of Southeast Asia and is under immediate threat.",historicalContext:"Following the communist victory in China in 1949 and Soviet recognition of the DRV in early 1950, the Truman administration pivoted from viewing the conflict as a colonial war to seeing Indochina as the critical linchpin of Southeast Asian containment.",whyItMatters:'Codified what Eisenhower would later describe as the "Domino Theory," directly leading to the U.S. underwriting up to 78–80% of French military expenditures in Vietnam by 1954.',originalDocumentUrl:"https://history.state.gov/historicaldocuments/frus1950v06/d480"}],nextQuestion:{question:"Why did a temporary line become a border?",framing:"The Geneva deal called the line at the 17th parallel temporary. Elections in 1956 were supposed to reunite the country, and they never took place."},citations:[o._["c1-1"],o._["c1-2"],o._["c1-3"]]},{id:"geneva-south-vietnam",number:2,timeframe:"1954–1960",leadImageId:"diem-eisenhower-1957",galleryImageIds:["dmz-map-1957","passage-to-freedom-1954","arvn-commandments-1956"],title:"Geneva splits Vietnam in two",subtitle:"The Geneva deal promised elections in 1956. Ngo Dinh Diem refused to hold them, and the South slid toward civil war.",summary:"The 1954 Geneva Accords divided Vietnam at the 17th parallel until nationwide elections in 1956. Those elections never happened. Ngo Dinh Diem took power in Saigon and refused them, the Cold War powers did not push, the North was busy rebuilding, and nobody enforced the deal. Diem’s land policies and his campaigns against communists angered many people in the countryside. With Hanoi’s backing, his opponents formed the National Liberation Front (NLF).",featuredDocument:{citationId:"Q026",kind:"Declaration",stamp:"FRUS 1952–1954, Vol. XIII",header:[["From","The Geneva Conference"],["Title","Final Declaration, paragraph 6"],["Date","July 21, 1954"]],note:"The conference called the line at the 17th parallel temporary, not a border. The 1956 elections that were supposed to reunite Vietnam never took place."},whatHappened:{narrative:["The Geneva Conference ended in July 1954 with a ceasefire that split Vietnam at the 17th parallel. The split was supposed to be temporary. For 300 days, people could cross the line freely. With help from U.S. Navy ships, about 890,000 people moved south in Operation Passage to Freedom. Most were Catholics, government workers and families who opposed the communists. About 100,000 Viet Minh fighters from the South went north.[^c2-2]","In Saigon, Ngo Dinh Diem became prime minister under Emperor Bao Dai. Diem was a strict Catholic and a nationalist. With American money and advisers, he defeated the Binh Xuyen crime syndicate and the armed religious sects. In 1955 he held a rigged vote that removed Bao Dai, and he declared the Republic of Vietnam. Geneva had set July 1956 as the deadline for elections across the whole country. When the deadline came, Diem refused to talk with Hanoi. He said a fair vote was impossible in the communist North. President Eisenhower later wrote in his memoirs that Ho Chi Minh would probably have won about 80 percent of the vote.[^c2-2]","Diem’s refusal was not the only reason the split became permanent. Geneva was a compromise among many countries, and neither the United States nor the Soviet Union was willing to enforce a vote. Hanoi was busy rebuilding its economy and carrying out a harsh land reform campaign from 1953 to 1956. No neutral body existed to run a nationwide election. In the South, Diem gave land that the Viet Minh had handed out back to the old landlords, and many villagers were furious. His campaign against communists wiped out much of their network in the South. In January 1959, Hanoi’s leaders passed Resolution 15, which approved armed struggle in the South.[^c2-1] In December 1960, they created the National Liberation Front, which Americans called the Viet Cong.[^c2-3]"],sections:[{date:"1954–1955",heading:"Vietnam splits, and nearly a million people move south"},{date:"1955–1956",heading:"Diem takes power and skips the vote"},{date:"1956–1960",heading:"The South turns against Diem"}],keyEvents:[{date:"July 21, 1954",title:"The Geneva Accords",detail:"A ceasefire is signed. Vietnam is split at the 17th parallel for now, with elections due in 1956."},{date:"1954–1955",title:"Operation Passage to Freedom",detail:"Nearly 900,000 refugees move from North to South. About 100,000 southern fighters move North."},{date:"Oct 26, 1955",title:"Diem declares the Republic of Vietnam",detail:"Ngo Dinh Diem becomes president after a rigged vote removes Bao Dai."},{date:"July 1956",title:"The 1956 elections never happen",detail:"The vote is never held. The temporary line hardens into a Cold War border."},{date:"Jan 1959",title:"Hanoi approves armed struggle",detail:"The Party approves armed revolution in the South. Group 559 starts building the Ho Chi Minh Trail."},{date:"Dec 20, 1960",title:"The National Liberation Front forms",detail:"Rebel groups in the South unite as the NLF in Tay Ninh province."}]},washington:{keyActors:["Dwight D. Eisenhower","John Foster Dulles","Edward Lansdale","Ngo Dinh Diem"],strategicObjective:"Build a stable, independent, non-communist South Vietnam with money and advisers, and keep American troops out of combat.",underlyingAssumptions:["Aid and training from the Military Assistance Advisory Group could make South Vietnam able to defend itself.","A divided Vietnam was better than a united one under Ho Chi Minh, which Washington counted as a Cold War loss.","Ngo Dinh Diem was the only nationalist who opposed both the communists and the French and could take charge in Saigon."],internalDebates:["In 1955 Ambassador J. Lawton Collins warned that Diem’s favoritism toward his family and his narrow support would bring trouble. He urged Washington to find someone else.","CIA officer Edward Lansdale and Secretary of State Dulles persuaded Eisenhower to stick with Diem."],homeFrontConstraints:["Eisenhower’s New Look national security policy prioritized fiscal restraint, reliance on nuclear deterrence, and regional alliances, strictly avoiding major Asian ground troop commitments."],primaryDocumentRef:"resolution-15-1959"},hanoi:{keyActors:["Le Duan","Ho Chi Minh","Truong Chinh","Pham Van Dong"],strategicObjective:"Rebuild the North after the war, strengthen socialism there and reunite the country.",underlyingAssumptions:["At first Hanoi expected the Geneva Accords and diplomatic pressure to deliver nationwide elections in 1956.","The Soviet Union and China urged patience and political struggle, because they did not want to draw American troops in."],internalDebates:["Truong Chinh wanted to put the North’s economy and land reform first. Le Duan, who had led the fight in the South, said that waiting while Diem hunted down southern communists would destroy them.","Le Duan’s side won in 1959 with Resolution 15, which approved armed struggle in the South."],homeFrontConstraints:["Severe rural disruption caused by the 1953–1956 northern land reform campaign, which resulted in widespread excesses, rural unrest in Nghe An, and public apologies from Ho Chi Minh."],primaryDocumentRef:"resolution-15-1959"},causalChain:{decision:{actor:"Ngo Dinh Diem and Washington; Hanoi’s leaders",action:"Diem skipped the 1956 elections and, with American money, built an anti-communist state. In 1959 Hanoi approved armed struggle in the South.",date:"1955–1959"},assumption:{premise:"Washington thought aid and police training would make Diem’s government strong. Hanoi thought guerrillas could bring Diem down without drawing in American troops.",blindSpot:"Diem’s land policy and his favoritism toward Catholics turned villagers against him. Each side also misjudged how far the other would go."},result:{immediate:"Guerrillas killed more of Diem’s village officials, the countryside grew less safe, and the NLF formed in December 1960.",counterAction:"John F. Kennedy took office in 1961 and sent many more military advisers, Special Forces and helicopter units."},unintendedConsequence:"An argument over who should rule Vietnam became a shooting war in the villages.",nextDecision:"How would Kennedy fight guerrillas that American weapons could not easily find?"},interactiveModule:{id:"geneva-division-map",type:"geneva-division-map",title:"The 17th parallel",prompt:"Explore the line that split Vietnam, from the Ben Hai River to the 300 days when anyone could cross it. Then see why it stayed."},primaryDocuments:[{id:"resolution-15-1959",registryId:"Q003",isVerified:!1,transcriptionStatus:"unverified_paraphrase",title:"Resolution 15 of the Vietnam Workers’ Party Central Committee",authorOrSpeaker:"Central Executive Committee, Workers’ Party of Vietnam",role:"Ruling Politburo / Central Committee, Hanoi",side:"hanoi",date:"January 1959",classification:"Internal Politburo Document (Secret)",archiveSource:"Wilson Center Cold War International History Project (CWIHP); Asselin, Hanoi’s Road to the Vietnam War",archiveId:"CWIHP Collection; Van Kien Dang Toan Tap, Vol. 20 (Paraphrase)",excerpt:"Adopted in January 1959, Resolution 15 designated violent struggle as the essential path for the revolution in South Vietnam, authorizing southern cadre to combine popular political mobilization with armed operations to dismantle the southern administration.",historicalContext:'Between 1954 and 1958, Hanoi prioritized socialist reconstruction and land reform in the North. But as Ngo Dinh Diem’s "Denounce the Communists" campaign decimated southern cadre networks, southern militants—led by Le Duan—pressured the Politburo to authorize armed struggle.',whyItMatters:"Marked the decisive transition from political agitation to armed revolutionary warfare in the South, creating Group 559 to construct what became the Ho Chi Minh Trail.",originalDocumentUrl:"https://www.wilsoncenter.org/program/cold-war-international-history-project"}],nextQuestion:{question:"Why did Washington turn against Diem?",framing:"John F. Kennedy sent more than 16,000 advisers to keep Diem in power. By November 1963, Washington was ready to see him go."},citations:[o._["c2-1"],o._["c2-2"],o._["c2-3"]]},{id:"kennedy-and-diem",number:3,timeframe:"1961–1963",leadImageId:"jfk-laos-1961",galleryImageIds:["saigon-street-1961","madame-nhu-1963","pentagon-papers-diem"],title:"Kennedy, Diem and the coup",subtitle:"Kennedy sent 16,000 advisers to save Diem’s government. In November 1963, South Vietnamese generals killed Diem, and Washington knew the coup was coming.",summary:"President Kennedy wanted to avoid a big land war that might pull in China. He chose counterinsurgency instead and raised the number of American advisers from about 900 to more than 16,000. It went badly. The Strategic Hamlet Program turned farmers against the government, the Battle of Ap Bac showed how weak South Vietnam’s army was, and Diem cracked down on the Buddhist majority. In November 1963, Washington signaled that it would accept a coup, and Diem was overthrown.",featuredDocument:{citationId:"Q004",kind:"Telegram",stamp:"FRUS 1961–1963, Vol. IV, Doc. 268",header:[["From","Department of State"],["To","Embassy Saigon"],["Number","243"],["Date","August 24, 1963"]],note:"Written by Roger Hilsman, Averell Harriman and George Ball, this cable told the embassy that Washington could live without Diem. On November 1–2, South Vietnamese generals overthrew him and killed him."},whatHappened:{narrative:["John F. Kennedy took office in 1961 in the middle of crises in Laos, Berlin and Cuba’s Bay of Pigs. He wanted to fight what Soviet leaders called wars of national liberation without sending large army units into combat, as in Korea. His answer was flexible response, with a focus on fighting guerrillas. He sent Green Beret Special Forces and helicopter units, and he approved tests of chemicals that kill plants. By late 1963, the number of U.S. military personnel in South Vietnam had grown from about 900 to more than 16,300. That buildup happened well before Diem was killed.[^c3-2]","In 1962, South Vietnam and its American advisers started the Strategic Hamlet Program. They built more than 8,000 fortified villages to cut farmers off from the Viet Cong.[^c3-1] Many villagers hated it. They were forced off land where their families had farmed and were buried, and corrupt local officials made things worse. In January 1963, the Battle of Ap Bac showed how weak the South Vietnamese army still was. It outnumbered the enemy eight to one and had armored vehicles and air support. A Viet Cong battalion of 350 men beat it anyway.[^c3-2]","In May 1963, government troops fired on Buddhist protesters in Hue, and the Buddhist Crisis began. On June 11, the monk Thich Quang Duc burned himself to death on a Saigon street in protest. Malcolm Browne’s photograph of it shocked people around the world. In August, Diem’s brother Ngo Dinh Nhu, who ran the security forces, raided Buddhist pagodas across the country. Washington answered with State Department Cable 243, drafted by Roger Hilsman. It signaled to South Vietnamese generals that the United States would back a new government if Diem did not get rid of Nhu.[^c3-3] On November 1–2, 1963, the generals overthrew Diem and killed him and Nhu. The United States knew the coup was coming and did not stop it. Three weeks later, Kennedy was assassinated in Dallas."],sections:[{date:"1961–1963",heading:"Kennedy sends advisers instead of armies"},{date:"1962–1963",heading:"Strategic hamlets and the defeat at Ap Bac"},{date:"May–November 1963",heading:"The Buddhist crisis and the coup"}],keyEvents:[{date:"Nov 1961",title:"Kennedy sends more advisers (NSAM 111)",detail:"Kennedy approves more U.S. advisers, aircraft units and combat support."},{date:"Feb 1962",title:"MACV is set up",detail:"The U.S. sets up Military Assistance Command, Vietnam, under General Paul Harkins."},{date:"March 1962",title:"The Strategic Hamlet Program starts",detail:"Farmers across the country begin to be moved into fortified villages."},{date:"Jan 2, 1963",title:"The Battle of Ap Bac",detail:"A Viet Cong battalion beats a much larger ARVN force and exposes weak leadership."},{date:"June 11, 1963",title:"A monk burns himself in protest",detail:"Thich Quang Duc’s death in Saigon sets off outrage around the world at Diem’s treatment of Buddhists."},{date:"Aug 24, 1963",title:"Cable 243",detail:"Washington signals to South Vietnamese generals that it will not stand in the way of removing Diem."},{date:"Nov 1–2, 1963",title:"The coup and Diem’s death",detail:"ARVN generals overthrow and kill Diem and Nhu. The U.S. is left responsible for the chaos that follows."}]},washington:{keyActors:["John F. Kennedy","Robert S. McNamara","Henry Cabot Lodge Jr.","Roger Hilsman","McGeorge Bundy"],strategicObjective:"Beat the guerrillas with counterinsurgency while pushing Diem to reform his government and army.",underlyingAssumptions:["Helicopters, chemical defoliants and Special Forces could solve what was really a political fight for the villages.","A government led by South Vietnamese generals would win more support and fight better than Diem."],internalDebates:["Averell Harriman, Roger Hilsman and Ambassador Henry Cabot Lodge argued that Diem had lost his people and could not win.","Vice President Johnson, General Maxwell Taylor and CIA Director John McCone warned that removing Diem would bring chaos."],homeFrontConstraints:["Emergence of critical investigative reporting from Saigon correspondents (David Halberstam, Neil Sheehan, Malcolm Browne) challenging official military optimism."],primaryDocumentRef:"cable-243-diem"},hanoi:{keyActors:["Le Duan","Nguyen Chi Thanh","Ho Chi Minh","Vo Nguyen Giap"],strategicObjective:"Break up the strategic hamlets, beat South Vietnam’s army in the field and take advantage of the turmoil in Saigon.",underlyingAssumptions:["Saigon’s government was held together mostly by American support, and Diem’s fall would leave it paralyzed.","The United States would hesitate to send combat troops as long as the guerrillas kept up the pressure."],internalDebates:["In December 1963 Le Duan won approval for Resolution 9, which sent regular North Vietnamese army regiments south to strike before the United States could step in.","Party leaders who urged caution about fighting American forces lost influence."],homeFrontConstraints:["Managing escalating Sino-Soviet ideological friction while ensuring steady logistical deliveries of weapons from both communist powers."],primaryDocumentRef:"cable-243-diem"},causalChain:{decision:{actor:"The Kennedy administration and South Vietnamese generals",action:"Washington signaled in Cable 243 that it would accept a coup. Generals overthrew Diem and killed him and his brother Nhu.",date:"August–November 1963"},assumption:{premise:"A new military government would pull the country together and fight harder.",blindSpot:"Diem was the one leader holding Saigon’s quarreling generals together. Without him, they turned on each other."},result:{immediate:"Saigon went through a string of short-lived military governments. Desertions rose, and the Viet Cong took over more of the countryside.",counterAction:"Hanoi passed Resolution 9 and started sending regular North Vietnamese army units south on the Ho Chi Minh Trail."},unintendedConsequence:"By helping remove Diem, the United States made itself responsible for whatever came next in Saigon.",nextDecision:"With South Vietnam close to collapse in 1964, would Lyndon Johnson look for a way out, or go to war?"},interactiveModule:{id:"escalation-timeline",type:"escalation-timeline",title:"From 900 advisers to 16,000",prompt:"Follow the numbers year by year, from 900 advisers in 1960 to more than 16,000 in 1963, and watch advising turn into fighting."},primaryDocuments:[{id:"cable-243-diem",registryId:"Q004",isVerified:!0,transcriptionStatus:"source_transcription",title:"State Department Cable 243 to Embassy Saigon (The Coup Cable)",authorOrSpeaker:"George Ball, Averell Harriman, and Roger Hilsman",role:"U.S. Department of State",side:"washington",date:"August 24, 1963",classification:"TOP SECRET // OPERATIONAL IMMEDIATE",archiveSource:"Foreign Relations of the United States (FRUS), 1961–1963, Vol. IV",archiveId:"FRUS 1961–1963, Vol. IV, Document 268 (Telegram 243)",excerpt:"US Government cannot tolerate situation in which power lies in Nhu's hands. Diem must be given chance to rid himself of Nhu and his coterie and replace them with best military and political personalities available. If, in spite of all of your efforts, Diem remains obdurate and refuses, then we must face the possibility that Diem himself cannot be preserved.",historicalContext:"Drafted over a weekend when President Kennedy, Dean Rusk, and Robert McNamara were away from Washington, this cable signaled to South Vietnamese generals that the U.S. would not oppose a military coup against Ngo Dinh Diem following the raids on Buddhist pagodas.",whyItMatters:"The ensuing November 1, 1963 coup and assassination of Diem eliminated the civilian leadership of South Vietnam, creating a cycle of military juntas that drew Washington into direct institutional ownership of the regime.",originalDocumentUrl:"https://history.state.gov/historicaldocuments/frus1961-63v04/d268"}],nextQuestion:{question:"What really happened in the Gulf of Tonkin?",framing:"President Johnson told Americans that North Vietnam had attacked U.S. destroyers twice, in international waters, for no reason. The Navy’s own records tell a different story about the second night."},citations:[o._["c3-1"],o._["c3-2"],o._["c3-3"]]},{id:"gulf-of-tonkin",number:4,timeframe:"1964",leadImageId:"tonkin-p4-1964",title:"The Gulf of Tonkin",subtitle:"Two nights at sea in August 1964, and the vote in Congress that followed",summary:"On August 2, 1964, North Vietnamese torpedo boats fought the destroyer USS Maddox in daylight. That clash was real. On August 4, in a storm, U.S. ships reported a second attack. Navy commanders and NSA analysts soon doubted it, but the Johnson administration presented it as a clear attack. Congress passed the Gulf of Tonkin Resolution almost unanimously.",isLandmark:!0,layout:"layered",story:{objectives:{ah1:["Describe what happened on August 2 and August 4, 1964","Explain what the Gulf of Tonkin Resolution allowed the president to do","Explain how the resolution led to a much larger war in 1965"],apush:["Explain the causes and effects of the Gulf of Tonkin Resolution (Topic 8.8)","Analyze how it shaped debates over presidential war power through 1973 (KC-8.1.II.C.ii)","Evaluate two competing explanations of why Washington acted on August 4"]},beats:[{id:"covert",kicker:"January–July 1964",headline:"A secret war along the coast",body:["In early 1964, the United States began backing secret raids on North Vietnam’s coast. Under a plan called OPLAN 34A, South Vietnamese commandos struck radar sites and islands.","At the same time, U.S. Navy destroyers sailed the Gulf of Tonkin on spy missions called DeSoto patrols. They recorded North Vietnam’s radio and radar signals. On July 31, commandos shelled Hon Me Island while the destroyer Maddox was offshore. To Hanoi, the raids and the patrols looked like one operation."]},{id:"august-2",imageId:"tonkin-track-chart-1964",kicker:"August 2, 1964",headline:"A real fight in daylight",body:["On the afternoon of August 2, three North Vietnamese torpedo boats raced toward the Maddox. The American commander on board sent a warning and got ready to fire.[^Q024]","In the fight that followed, planes from the carrier Ticonderoga damaged the boats. The Maddox was hit by a single machine-gun bullet."],visual:{kind:"quote",citationId:"Q024"}},{id:"august-4",kicker:"Night of August 4, 1964",headline:"A night of confusion",body:["Two nights later, the Maddox and a second destroyer, the Turner Joy, were back in the gulf. A storm rolled in after dark. Then the radar screens lit up."],visual:{kind:"night",question:"What did Washington know, and when?",instruction:"Scroll through the night and watch both clocks.",takeaway:"Doubts from the scene reached Washington about ten hours before the president announced air strikes. The commander reported no visual sightings, and the pilot overhead saw no enemy boats.",caption:"Scenes are illustrations, not plotted data. Gulf time is 11 hours ahead of Washington. The cable and broadcast times are from the records; the first three times are approximate.",citationId:"c4-1",steps:[{localTime:"Aug 4, 9:30 p.m.",washingtonTime:"Aug 4, 10:30 a.m.",scene:"contacts",headline:"Blips in the storm",body:"In rain and darkness, radar operators on the Maddox saw blips they took for enemy boats. No one on the Maddox actually saw an enemy boat.[^Q013]"},{localTime:"Aug 4, 10:15 p.m.",washingtonTime:"Aug 4, 11:15 a.m.",scene:"firing",headline:"Firing into the dark",body:"Sonar operators reported torpedoes in the water. Both destroyers fired more than 600 rounds at the radar contacts."},{localTime:"Aug 4, 11:00 p.m.",washingtonTime:"Aug 4, 12:00 p.m.",scene:"overhead",headline:"A pilot sees nothing",body:"Navy pilot James Stockdale flew low over the destroyers, looking for the enemy. He saw the ships’ wakes and their gunfire, and nothing else.[^Q021]",quoteCitationId:"Q021"},{localTime:"Aug 5, 12:27 a.m.",washingtonTime:"Aug 4, 1:27 p.m.",scene:"cable",headline:"The commander has doubts",body:"Captain John Herrick, in command at sea, sent a flash cable. He said many of the reports looked doubtful and asked for a full review before anyone acted.[^Q013]",quoteCitationId:"Q013"},{localTime:"Aug 5, 10:36 a.m.",washingtonTime:"Aug 4, 11:36 p.m.",scene:"broadcast",headline:"The president goes on TV",body:"About ten hours after Herrick’s cable, President Johnson spoke on national television. He said U.S. ships had been attacked again, and that American planes were already striking back.[^Q027]",quoteCitationId:"Q027"}]},checkId:"c4-q2"},{id:"two-nights",kicker:"August 2 vs. August 4",headline:"The two nights compared",body:["Historians agree on what happened on August 2. Using records released decades later, they also agree that the August 4 attack most likely never happened.[^c4-2]"],visual:{kind:"compare",question:"How do the two nights compare?",rowLabels:["Conditions","Evidence at the time","What later research found"],columns:[{label:"August 2",verdict:"Attack confirmed",cells:["Afternoon, in daylight.","The Maddox reported torpedo boats closing in and prepared to fire.[^Q024]","Three torpedo boats fought the Maddox; one bullet hit the ship."]},{label:"August 4",verdict:"Most likely no attack",cells:["Night, in heavy rain and total darkness.","Radar and sonar reports, plus radio intercepts later shown to describe August 2.[^c4-2] The Maddox had no visual sightings.[^Q013]","The NSA’s own historian concluded that no attack took place that night.[^Q005]"]}],takeaway:"One clash was real. The second, which led Congress to act, most likely was not.",citationId:"c4-1"},checkId:"c4-q1"},{id:"resolution",imageId:"lbj-tonkin-signing-1964",moreImageIds:["tonkin-resolution-1964"],kicker:"August 4–7, 1964",headline:"Washington acts fast",body:["Johnson ordered air strikes on North Vietnamese naval bases, called Operation Pierce Arrow. He was also running for president against Barry Goldwater, who called the administration weak.[^c4-3]","Three days later, Congress passed the Gulf of Tonkin Resolution. It let the president use force to repel attacks and prevent further aggression, without a declaration of war.[^Q006]"],visual:{kind:"debate",question:"Should Congress give the president this much power?",sides:[{stance:"Yes",who:"President Johnson and most of Congress",argument:"Attacks on U.S. ships called for a firm reply, and a united Congress would show Hanoi that America meant it."},{stance:"No",who:"Senators Wayne Morse and Ernest Gruening",argument:"The resolution handed Congress’s war power to the president, based on reports nobody had checked."}],outcome:"It passed 416–0 in the House and 88–2 in the Senate. Only Morse and Gruening voted no."},checkId:"c4-q3"},{id:"blank-check",kicker:"1965–1973",headline:"Congress hands over its war power, then takes it back",body:["The resolution did not declare war, but it worked like one. When Viet Cong forces attacked U.S. barracks at Pleiku in February 1965, Johnson already had the power to escalate. Within weeks, steady bombing began and U.S. combat troops landed.","Years later, Congress tried to take that power back. The War Powers Resolution of 1973 says a president can send troops into combat only after a declaration of war, a specific law, or an attack on the United States.[^Q029] It passed over President Nixon’s veto."],visual:{kind:"consequence"},checkId:"c4-q4"}],debate:{question:"Did the Johnson administration mislead Congress, or rush to judgment?",agreed:"Historians now agree that no attack took place on August 4.[^Q005] They disagree about why Washington acted as if one had.",positions:[{label:"A rush to judgment",claim:"Officials acted fast on confused early reports. The worst errors came from how intelligence was handled, not from a plan to lie.[^c4-1]",evidence:["Moise’s reconstruction does not claim that Johnson knowingly lied.[^c4-1]","The NSA study blamed mid-level analysts who filtered intercepts, not top officials.[^c4-2]","McNamara later called it confusion and admitted the attack did not happen.[^Q023]"]},{label:"An opportunity seized",claim:"The administration wanted broad authority for a wider war and used the incident to get it.[^c4-3]",evidence:["The text of a congressional resolution had been drafted months before August 1964.[^c4-3]","Herrick’s doubts reached Washington about ten hours before the president spoke.[^Q013]","Johnson was campaigning against Goldwater, who called the administration weak.[^c4-3]"]}]},evidence:["Q024","Q013","Q021","Q027","Q006","Q022","Q028","Q005","Q023","Q029"],tasks:{ah1:[{kind:"order",prompt:"Put these events in the order they happened.",items:[{label:"Secret commando raids on North Vietnam begin (OPLAN 34A)",date:"January 1964"},{label:"Commandos shell Hon Me Island",date:"July 31, 1964"},{label:"Torpedo boats attack the Maddox in daylight",date:"August 2, 1964"},{label:"Johnson announces air strikes on television",date:"August 4, 1964"},{label:"Congress passes the Gulf of Tonkin Resolution",date:"August 7, 1964"}]},{kind:"explain",prompt:"In your own words, how was August 2 different from August 4?",starters:["On August 2,","On August 4,","The difference matters because"],checklist:["August 2 was a real attack, in daylight","August 4 was reports at night, in a storm, with no sightings","Later research found no attack on August 4","The August 4 reports led to the resolution"],model:"On August 2, North Vietnamese torpedo boats really did fight the Maddox in daylight. On August 4, the destroyers reported an attack at night in a storm, but nobody saw an enemy boat, and later research found there was no attack. The difference matters because the August 4 reports are what Congress acted on."},{kind:"explain",prompt:"Why did Congress give President Johnson so much power in August 1964?",starters:["Congress believed that","Most members voted yes because","This mattered later because"],checklist:["Names the reported attack on U.S. ships","Notes that Congress was not told about the doubts from the scene","Explains that the president could now use force without a declaration of war","Connects the resolution to the larger war in 1965"],model:"Congress was told that North Vietnam had attacked U.S. ships twice, and members wanted to back the president in a crisis. They were not told that the commander at sea doubted the second attack. The resolution let Johnson use force without declaring war, and he relied on it when he began heavy bombing and sent combat troops in 1965."}],apush:[{kind:"stimulus",citationId:"Q013",intro:"Read the cable, then answer the questions.",questions:[{id:"c4-s1",question:"The cable most directly supports which conclusion?",options:["Naval officers had confirmed a coordinated torpedo attack on both ships","North Vietnam had admitted attacking the destroyers during the night","The commander at sea doubted that a second attack had taken place","Congress had approved air strikes before the incident was reported"],correctIndex:2,rationale:"Herrick reports that many contacts and torpedo reports appear doubtful, notes no visual sightings, and asks for a full evaluation before further action."},{id:"c4-s2",question:"Which development followed most directly from the reports this cable questioned?",options:["Congress gave the president broad power to use force in Southeast Asia","The United States formally declared war on North Vietnam that month","Congress passed the War Powers Resolution to limit the president","The Soviet Union sent warships to defend the North Vietnamese coast"],correctIndex:0,rationale:"Three days later Congress passed the Gulf of Tonkin Resolution. The United States never declared war, and the War Powers Resolution came nine years later."},{id:"c4-s3",question:"Historians most often use this cable as evidence in debates over which question?",options:["Whether containment should also have applied to Latin America","Whether the draft fell unfairly on working-class Americans","Whether the Marshall Plan helped stop communism in Western Europe","Whether officials acted on doubtful intelligence in August 1964"],correctIndex:3,rationale:"The cable shows that doubts existed before the administration acted, which is central to debates over intelligence and presidential war power."}]},{kind:"saq",citationId:"Q005",intro:"Answer (a), (b), and (c) using the excerpt from a historian.",parts:[{label:"a",prompt:"Briefly describe the historian’s argument in the excerpt.",model:"The historian, Robert Hanyok of the NSA, argues that the second attack on August 4, 1964 did not happen at all, not just that it happened differently than reported."},{label:"b",prompt:"Briefly explain ONE piece of historical evidence that supports the argument.",model:"Captain Herrick’s flash cable that night said many contacts looked doubtful and that the Maddox had no visual sightings. A Navy pilot flying overhead also saw no enemy boats."},{label:"c",prompt:"Briefly explain ONE way the Gulf of Tonkin Resolution affected U.S. policy in Vietnam between 1964 and 1975.",model:"Johnson used the resolution as legal authority to escalate without a declaration of war, starting sustained bombing and sending combat troops in 1965. Concern about that blank check later helped lead Congress to pass the War Powers Resolution in 1973."}]},{kind:"leq",prompt:"Evaluate the extent to which the Vietnam War changed the balance of power between the president and Congress over military decisions from 1964 to 1975.",reasoning:"Continuity and change",scaffold:[{label:"Thesis",hint:"Take a position on how much changed, with your line of reasoning in one or two sentences."},{label:"Context",hint:"Describe the Cold War pattern before 1964, such as presidents committing forces in Korea without a declaration of war."},{label:"Evidence of presidential power",hint:"For example, the Gulf of Tonkin Resolution (1964) and the escalation that followed in 1965."},{label:"Evidence of congressional pushback",hint:"For example, the Cooper-Church Amendment (1970), the Case-Church Amendment (1973), and the War Powers Resolution (1973)."},{label:"Complexity",hint:"Explain what did not change, or why the War Powers Resolution limited presidents less than Congress hoped."}]}]}},landmarkMoment:{bannerTitle:"Two nights in the Gulf of Tonkin",dateline:"August 2 & 4, 1964",location:"Gulf of Tonkin, South China Sea",quote:"Review of action makes many reported contacts and torpedoes fired appear doubtful. Freak weather effects on radar and overeager sonarmen may have accounted for many reports. No actual visual sightings by Maddox. Suggest complete evaluation before any further action taken.",quoteCitationId:"Q013",quoteSpeaker:"Captain John J. Herrick, CTG 72.1",quoteContext:"Operational Flash Cable DTG 041727Z AUG 64 (FRUS 1964–1968, Vol. I, Doc 117)"},personalStory:{name:"James Stockdale",role:"Navy commander and fighter pilot, USS Ticonderoga, 1964",paragraphs:["On the night of August 4, 1964, Commander James Stockdale was flying an F-8 Crusader low over the Gulf of Tonkin, looking for the enemy torpedo boats the destroyers below were reporting. He circled above them for well over an hour. He saw the destroyers’ wakes and their gunfire, and nothing else.","The next morning he was ordered to lead an airstrike against North Vietnam in retaliation for the attack he had just watched not happen. He flew the mission.","Thirteen months later, in September 1965, Stockdale was shot down over North Vietnam and taken prisoner. Through years of interrogation in Hoa Lo prison, he carried a private fear: that his captors would learn he was the pilot who knew the truth about August 4."],quoteCitationId:"Q021",afterward:"Released in February 1973 after seven and a half years as a prisoner of war, Stockdale received the Medal of Honor in 1976. He told the Tonkin story with his wife, Sybil, in their 1984 memoir. She had spent his captivity organizing the families of missing and imprisoned servicemen."},featuredDocument:{citationId:"Q013",kind:"Flash telegram",stamp:"FRUS 1964–1968, Vol. I, Doc. 117",header:[["From","CTG 72.1 (USS Maddox)"],["To","CINCPACFLT"],["Sent","041727Z AUG 64"]],note:"Captain John Herrick sent this from the Maddox after the reported attack of August 4. CINCPACFLT is the Navy’s Pacific Fleet command. About ten hours later, President Johnson went on television to announce air strikes."},whatHappened:{narrative:["Throughout 1964, South Vietnam’s military situation worsened rapidly following Diem’s death. The Johnson administration initiated OPLAN 34A—covert South Vietnamese commando raids against North Vietnamese coastal radar installations and islands, coordinated alongside U.S. Navy DeSoto intelligence patrols collecting electronic signals in the Gulf of Tonkin.","On the afternoon of August 2, 1964, three North Vietnamese P-4 torpedo boats engaged the USS Maddox in international waters.[^Q024] Because South Vietnamese patrol boats had shelled radar towers on nearby Hon Me Island two days earlier, North Vietnamese naval commanders viewed the Maddox as an integral element of the operation. In the ensuing firefight, carrier aircraft from the USS Ticonderoga damaged the torpedo boats, while the Maddox was struck by a single 14.5mm machine-gun bullet.","Two nights later, on August 4, in heavy rain and total darkness, the Maddox and the USS Turner Joy reported coming under continuous torpedo attack, firing over 600 rounds at radar contacts. Hours later, task group commander Captain John Herrick cabled Washington urging caution, reporting that many reported contacts and torpedo firings appeared doubtful:[^Q013] “Review of action makes many reported contacts and torpedoes fired appear doubtful...” Subsequent declassified naval track reconstructions by Edwin Moise[^c4-1] and official NSA historical analysis by Robert Hanyok[^c4-2] demonstrated conclusively that intercepted North Vietnamese communications cited as proof of an attack actually described the salvage operations of boats damaged on August 2. Facing an election campaign against conservative Barry Goldwater, President Johnson presented the incident as an unprovoked attack, ordered retaliatory airstrikes (Operation Pierce Arrow), and secured passage of the Gulf of Tonkin Resolution.[^c4-3]"],keyEvents:[{date:"Jan 1964",title:"OPLAN 34A is approved",detail:"Secret raids by sea along North Vietnam’s coast begin."},{date:"July 31, 1964",title:"The raid on Hon Me Island",detail:"South Vietnamese boats shell radar sites on the northern coast while the Maddox sails offshore."},{date:"Aug 2, 1964",title:"The first Tonkin clash",detail:"Three North Vietnamese torpedo boats fight the USS Maddox in daylight. This one is confirmed."},{date:"Aug 4, 1964",title:"The second “attack”",detail:"Destroyers fire into dark, stormy water at radar and sonar contacts. Captain Herrick sends a cable saying he has doubts."},{date:"Aug 4, 1964 (Night)",title:"Operation Pierce Arrow",detail:"Johnson goes on national television to announce air strikes on North Vietnamese naval bases."},{date:"Aug 7, 1964",title:"Congress passes the Tonkin Resolution",detail:"The vote is 416–0 in the House and 88–2 in the Senate. Morse and Gruening vote no."}]},washington:{keyActors:["Lyndon B. Johnson","Robert S. McNamara","Dean Rusk","Adm. U.S. Grant Sharp Jr.","Sen. Wayne Morse"],strategicObjective:"Show Hanoi that America meant business, steady the Saigon government and answer Barry Goldwater’s charge that Johnson was weak.",underlyingAssumptions:["A sharp show of American air power would convince Hanoi that backing the southern guerrillas cost too much.","Congress could hand the president broad power to use force, to be held in reserve, without a declaration of war or a long debate."],internalDebates:["McNamara and the military relied on radio intercepts that seemed to confirm an attack, and set aside Captain Herrick’s cables asking them to wait.","Senators Wayne Morse and Ernest Gruening warned that the resolution gave away Congress’s war power on the basis of unchecked claims.[^Q022]"],homeFrontConstraints:["The 1964 presidential campaign: Johnson campaigned as the prudent candidate against Goldwater, promising not to send “American boys 9 or 10,000 miles away from home to do what Asian boys ought to be doing for themselves.”[^Q028]"],primaryDocumentRef:"tonkin-resolution-1964"},hanoi:{keyActors:["Le Duan","Ho Chi Minh","General Vo Nguyen Giap","Nguyen Chi Thanh"],strategicObjective:"Defend the coast against the OPLAN 34A raids and keep supplies moving to the guerrillas in the South.",underlyingAssumptions:["The American spy patrols and the South Vietnamese commando raids were one operation against North Vietnam.","An open American war was coming whether or not Hanoi held back."],internalDebates:["On August 2, local naval commanders attacked because they believed the Maddox was guiding the commando boats.","Hanoi said its boats took part in no fighting on the night of August 4."],homeFrontConstraints:["Constructing extensive civil defense networks, digging sidewalk bomb shelters, and preparing northern infrastructure for sustained American aerial bombardment."],primaryDocumentRef:"hanyok-tonkin-nsa"},causalChain:{decision:{actor:"Lyndon Johnson and Congress",action:"Congress passed the Gulf of Tonkin Resolution after the administration presented doubtful reports of a second attack as fact.",date:"August 7, 1964"},assumption:{premise:"Johnson saw the resolution as a warning to Hanoi and political cover in an election year. He thought it would help prevent a wider war.",blindSpot:"Hanoi read the American air strikes as proof that a full war was coming, and got ready for one."},result:{immediate:"Johnson won the November 1964 election in a landslide, holding open-ended legal authority to use force.",counterAction:"Hanoi sent its first full regiments of regular troops south on the Ho Chi Minh Trail."},unintendedConsequence:"When the Viet Cong attacked the U.S. base at Pleiku in February 1965, Johnson already had the power to escalate and few easy ways to back down.",nextDecision:"With Saigon’s government close to collapse in early 1965, would Johnson send in ground troops?"},interactiveModule:{id:"tonkin-reconstruction",type:"tonkin-reconstruction",title:"August 2 and August 4, side by side",prompt:"Put the two nights next to each other. See why August 2 was a real fight, and how bad weather, radar errors and selective use of intelligence produced the reports of August 4."},primaryDocuments:[{id:"tonkin-resolution-1964",registryId:"Q006",isVerified:!0,transcriptionStatus:"source_transcription",title:"The Gulf of Tonkin Resolution (Joint Resolution of Congress, Public Law 88-408)",authorOrSpeaker:"88th United States Congress",role:"Legislative Branch of the United States",side:"washington",date:"August 7, 1964",classification:"Public Law",archiveSource:"U.S. National Archives Milestone Documents / 78 Stat. 384",archiveId:"Public Law 88-408 / 78 Stat. 384, Section 1",excerpt:"Resolved by the Senate and House of Representatives of the United States of America in Congress assembled, That the Congress approves and supports the determination of the President, as Commander in Chief, to take all necessary measures to repel any armed attack against the forces of the United States and to prevent further aggression.",historicalContext:"Passed 416–0 in the House and 88–2 in the Senate within three days of reported naval engagements in the Gulf of Tonkin. Dissenting senators Wayne Morse and Ernest Gruening warned that Congress was unconstitutionally abdicating war powers on unverified evidence.",whyItMatters:"Served as the functional legal authorization utilized by the Johnson administration to conduct a major, undeclared ground and air war in Southeast Asia.",originalDocumentUrl:"https://www.archives.gov/milestone-documents/tonkin-gulf-resolution"},{id:"hanyok-tonkin-nsa",registryId:"Q005",isVerified:!0,transcriptionStatus:"source_transcription",title:'Cryptologic Analysis: "Skunks, Bogies, Silent Hounds, and the Flying Fish"',authorOrSpeaker:"Robert J. Hanyok",role:"Historian, National Security Agency (Center for Cryptologic History)",side:"washington",date:"Winter 2000 / Spring 2001 (Declassified 2005)",classification:"TOP SECRET // COMINT-CHANNELS (Declassified)",archiveSource:"National Security Archive Electronic Briefing Book No. 132 / NSA Cryptologic Quarterly",archiveId:"Cryptologic Quarterly, Vol. 19/20, p. 1 / NSA-EBB-132",excerpt:"First, it is not simply that there is a different story as to what happened; it is that no attack happened that night.",historicalContext:'An exhaustive internal NSA investigation into the cryptologic records of August 4, 1964. Hanyok demonstrated that intercepted North Vietnamese communications cited by the Johnson administration as "proof" of an attack actually described the tow operations of torpedo boats damaged two days earlier.',whyItMatters:"Proves through official intelligence records that the August 4 incident was not simply confused sailors in a storm, but an instance where ambiguous signals intelligence was selectively summarized upstream to fit an established administration objective.",originalDocumentUrl:"https://nsarchive2.gwu.edu/NSAEBB/NSAEBB132/"}],nextQuestion:{question:"Can you win a war by counting the dead?",framing:"General William Westmoreland believed the United States could kill North Vietnamese soldiers faster than Hanoi could replace them. He called that moment the crossover point, and it never came."},citations:[o._["c4-1"],o._["c4-2"],o._["c4-3"]]},{id:"americanization-attrition",number:5,timeframe:"1965–1967",leadImageId:"da-nang-1965",galleryImageIds:["aggression-north-1965","rolling-thunder-1966","lbj-cam-ranh-1966","ia-drang-1965","morse-fulbright-1966","king-antiwar-1967","pentagon-flower-1967"],title:"America takes over the war",subtitle:"In 1965 Lyndon Johnson sent combat troops and started bombing the North. By the end of 1967, about 485,000 Americans were in Vietnam.",summary:"In early 1965, Lyndon Johnson made Vietnam an American war. He launched the bombing campaign Operation Rolling Thunder, and by late 1967 more than 485,000 U.S. troops were in Vietnam. General William Westmoreland fought a war of attrition, trying to reach a crossover point. In Hanoi, First Secretary Le Duan took control from more cautious leaders. He pushed for big offensives and prepared the North to live through heavy bombing.",whatHappened:{narrative:["In February 1965, the Viet Cong attacked the U.S. base at Pleiku. President Johnson answered with Operation Rolling Thunder, a long bombing campaign against North Vietnam. The idea was called graduated pressure: raise the bombing step by step until Hanoi agreed to talk, without pulling China or the Soviet Union into the war. On March 8, 1965, two battalions of Marines landed at Da Nang. They were the first U.S. ground combat troops in Vietnam, and the American role changed from advising to fighting.[^c5-3]","General William Westmoreland’s plan was attrition: kill enemy soldiers faster than they could be replaced. His troops went on search-and-destroy missions backed by heavy firepower, and progress was measured in body counts.[^c5-2] In November 1965, the 1st Cavalry Division fought North Vietnamese army regiments in the Ia Drang Valley. The Americans killed more than ten enemy soldiers for every one they lost. Westmoreland took this as proof that he could reach the crossover point, when the enemy would lose men faster than it could replace them. But the communist side started about 75 to 80 percent of the firefights. That let them choose when to fight and when to slip back across the border to safety. About 200,000 young men came of draft age in North Vietnam every year, more than enough to replace the losses. In 1967, the U.S. command in Saigon quietly stopped publishing its estimates of how many enemy troops were coming south.[^c5-1]","In Hanoi, a power struggle was going on that Washington barely saw. By the mid-1960s, Ho Chi Minh’s role was mostly ceremonial, and First Secretary Le Duan made the big decisions.[^c5-1] General Vo Nguyen Giap and others wanted a slow guerrilla war. Le Duan wanted big offensives, and he won by arresting hundreds of moderates in what became known as the Anti-Party Affair. At home, all of North Vietnam was organized for war. Concrete one-person shelters lined Hanoi’s sidewalks, and city people were moved to the countryside. More than 230,000 Youth Volunteers, over half of them women, kept the Ho Chi Minh Trail open under constant bombing.[^c5-1]"],sections:[{date:"February–March 1965",heading:"Johnson sends in the Marines"},{date:"1965–1967",heading:"Counting bodies"},{date:"1965–1967",heading:"Meanwhile, in Hanoi"}],keyEvents:[{date:"March 2, 1965",title:"Rolling Thunder begins",detail:"A three-year bombing campaign against North Vietnam starts."},{date:"March 8, 1965",title:"Marines land at Da Nang",detail:"3,500 Marines arrive, the first American ground combat troops."},{date:"July 28, 1965",title:"Johnson sends 125,000 troops",detail:"Johnson commits 125,000 troops and doubles the monthly draft, without declaring a national emergency."},{date:"Nov 14–18, 1965",title:"The Battle of the Ia Drang Valley",detail:"The first big clash between U.S. helicopter troops and North Vietnamese regulars, at landing zones X-Ray and Albany."},{date:"1967",title:"The purge in Hanoi",detail:"Le Duan tightens his grip on power and arrests hundreds of party moderates who doubted a fast escalation."},{date:"Nov 21, 1967",title:"Westmoreland says the end is in sight",detail:"The U.S. commander tells Americans the enemy is running out of men."}]},washington:{keyActors:["Lyndon B. Johnson","Robert S. McNamara","Gen. William Westmoreland","Gen. Earle Wheeler"],strategicObjective:"Kill communist soldiers faster than Hanoi could replace them, so it would give up the war in the South, without drawing in China or the Soviet Union.",underlyingAssumptions:["Firepower, helicopters and body counts could show whether America was winning against a country of farmers.","North Vietnam had a breaking point, and enough losses would push it to negotiate."],internalDebates:["In 1965 Undersecretary of State George Ball warned that once American troops entered combat, the country would be stuck in a war it could not finish.","By mid-1967 Robert McNamara had privately decided that Rolling Thunder was not working and that attrition would cost too much."],homeFrontConstraints:["Rising anti-war sentiment, draft card burnings, and the March on the Pentagon in October 1967.","Budgetary strain: funding both the Great Society and the war without raising taxes ignited severe domestic inflation."],primaryDocumentRef:"cia-memo-giap-thanh-1966"},hanoi:{keyActors:["Le Duan","General Vo Nguyen Giap","Nguyen Chi Thanh","Ho Chi Minh"],strategicObjective:"Fight a long war, take the bombing, keep the trail open and outlast America’s patience.",underlyingAssumptions:["American voters would not put up with a long, bloody war for a goal they did not understand.","By grabbing the enemy by the belt and fighting at close range, communist troops could keep American planes and artillery from firing."],internalDebates:["General Nguyen Chi Thanh wanted big battles against American units. Giap wanted to save his forces and fight as guerrillas.","Le Duan’s side overruled the moderates, arrested officers who disagreed and began planning a nationwide offensive."],homeFrontConstraints:["Surviving Operation Rolling Thunder: dispersing factories and hospitals into caves and rural areas, and enduring severe civilian rationing."],primaryDocumentRef:"mccarthy-hanoi-1968"},causalChain:{decision:{actor:"Johnson and Westmoreland; Le Duan in Hanoi",action:"Johnson sent nearly half a million troops to fight a war of attrition. Le Duan readied North Vietnam for one huge offensive.",date:"1965–1967"},assumption:{premise:"Washington thought Hanoi would run out of soldiers. Hanoi thought a nationwide attack on the cities would set off an uprising in the South.",blindSpot:"Washington counted bodies while the enemy chose when and where to fight. Hanoi overestimated how many southerners would rise up."},result:{immediate:"American firepower killed huge numbers of enemy soldiers, but men and supplies kept coming down the Ho Chi Minh Trail.",counterAction:"Hanoi finished its plans to attack South Vietnam’s cities all at once in early 1968."},unintendedConsequence:"Johnson’s officials kept telling Americans the war was being won. When the attack came, much of the public stopped believing them.",nextDecision:"How would Americans react when communist forces hit dozens of South Vietnamese cities on the same night?"},interactiveModule:{id:"attrition-model",type:"attrition-model",title:"The crossover point",prompt:"Set the enemy deaths the U.S. command reported against the number of soldiers North Vietnam could add each year. Then check who started most of the firefights."},primaryDocuments:[t,a],nextQuestion:{question:"What was the secret war behind the front lines?",framing:"While big American units fought in the highlands, the CIA went after the Viet Cong’s hidden government, and Air Force planes sprayed the jungle with chemicals."},citations:[o._["c5-1"],o._["c5-2"],o._["c5-3"]]},{id:"the-secret-war",number:6,timeframe:"1961–1972",leadImageId:"ranch-hand",galleryImageIds:["korean-marines-rice-1966","vc-prisoner-1967","chieu-hoi-poster","long-my-poster-1967","hamlet-population-map-1972"],title:"The secret war",subtitle:"Away from the big battles, the CIA ran an army in Laos and hunted the Viet Cong’s hidden government. Air Force planes sprayed the forests with Agent Orange.",summary:"Alongside the regular battles, the United States and South Vietnam fought a quieter war. The Phoenix Program went after the Viet Cong’s political network by identifying its members and capturing or killing them. Operation Ranch Hand sprayed millions of gallons of herbicide to strip away forest cover. The harm to people and to the land has lasted for decades.",whatHappened:{narrative:["Army sweeps could not destroy the Viet Cong’s hidden government. It collected taxes, ran schools and recruited fighters. So in 1967–1968, the CIA and South Vietnamese security agencies created the Phoenix Program, *Phung Hoang* in Vietnamese. It was run by CORDS (Civil Operations and Revolutionary Development Support). Phoenix pooled what the military and police knew in order to find the members of this hidden network and remove them by capture, persuasion or killing. Official figures given to Congress in 1971 counted 81,740 people removed: 33,358 captured, 22,013 who switched sides and 26,369 killed.[^c6-3] But testimony showed that about 87 percent of those killed died in regular military operations and artillery fire, not in targeted police actions. Monthly quotas led officials to pad their reports with ordinary combat deaths.[^c6-3]","From 1962 to 1971, the U.S. Air Force ran Operation Ranch Hand. Its planes sprayed about 19 million gallons of plant-killing chemicals over the South Vietnamese countryside to strip away the jungle cover and crops the guerrillas relied on.[^c6-2] About 11 million gallons were Agent Orange, which was contaminated with 2,3,7,8-TCDD, a dioxin that causes cancer and stays in the environment for years.[^c6-2] More than 5 million acres of forest and 500,000 acres of crops were stripped bare. The harm lasted for decades, with higher rates of cancer, birth defects and long-term illness among Vietnamese civilians and American veterans. Few people know that the contaminated UC-123 planes were later handed to the Air Force Reserve, which flew them on cargo missions inside the United States from 1972 to 1982.","At the same time, the CIA was running a large secret war in neighboring Laos. It organized an army of about 30,000 Hmong fighters under General Vang Pao to cut the Ho Chi Minh Trail.[^c6-1] With Air America transport planes and heavy secret B-52 raids, Laos became the most heavily bombed country per person in history.[^c6-2] Phoenix and the other pacification programs did damage the Viet Cong’s political network. But their rough methods and the civilians they killed turned many villagers against the government."],sections:[{date:"1967–1971",heading:"The Phoenix Program"},{date:"1962–1971",heading:"Operation Ranch Hand"},{date:"1961–1973",heading:"The war in Laos"}],keyEvents:[{date:"Nov 1961",title:"Kennedy approves chemical spraying",detail:"Diem asks for spraying from the air. Kennedy approves it one mission at a time as a test."},{date:"Jan 1962",title:"Operation Ranch Hand begins",detail:"Planes start spraying plant-killing chemicals over South Vietnam."},{date:"May 1967",title:"CORDS is set up",detail:"Robert Komer brings the civilian and military pacification efforts together under MACV."},{date:"July 1968",title:"The Phoenix Program starts",detail:"President Thieu orders Phung Hoang to find and break up the Viet Cong’s civilian network."},{date:"July 1971",title:"Congress holds hearings on Phoenix",detail:"William Colby and former intelligence soldiers tell the House about quotas and abuses."},{date:"1971–1972",title:"Ranch Hand ends",detail:"Spraying stops after scientific studies on dioxin poisoning and protests at home."}]},washington:{keyActors:["Robert Komer","William Colby","Richard Helms","Ngo Dinh Diem"],strategicObjective:"Destroy the Viet Cong’s hidden government and take away the jungle cover and crops the guerrillas lived on.",underlyingAssumptions:["The guerrillas depended on a network of officials who ruled by fear, and police work guided by good intelligence could take that network apart.","Herbicides were a cheap, efficient way to protect bases and convoys, with no lasting harm to the land."],internalDebates:["Critics in Congress and the press called Phoenix a program for assassinating civilians. The CIA defended it and said ordinary combat deaths had padded its numbers.","In 1961 State Department officials pushed back against spraying herbicides, because they feared the world would call it chemical warfare."],homeFrontConstraints:["Intense public and congressional scrutiny following revelations of interrogation abuses, tiger cages at Con Son Island, and chemical contamination."],primaryDocumentRef:"cia-memo-giap-thanh-1966"},hanoi:{keyActors:["Le Duan","Central Office for South Vietnam (COSVN)","Nguyen Van Linh"],strategicObjective:"Protect party members in the South, keep control of the villages and fight the pacification programs.",underlyingAssumptions:["Villagers’ nationalism and anger over land would let the Viet Cong rebuild its network no matter how many people were arrested.","American spraying would push villagers who had not taken sides toward the revolution."],internalDebates:["Communist headquarters in the South saw Phoenix as a serious threat. Between 1968 and 1971 it wrecked the party’s network in many provinces and forced officials to retreat to remote bases."],homeFrontConstraints:["Managing heavy loss of seasoned southern organizers, requiring northern administrative cadres to be dispatched south to replace fallen personnel."],primaryDocumentRef:"resolution-15-1959"},causalChain:{decision:{actor:"The CIA, the U.S. command and South Vietnam’s government",action:"They set up the Phoenix Program to remove the Viet Cong’s hidden officials, and sprayed herbicides to strip away the jungle cover.",date:"1962–1971"},assumption:{premise:"Take away the hidden government and the jungle cover, and the guerrillas would lose their hold on the villages.",blindSpot:"Arrest quotas and chemical spraying hurt ordinary villagers, and many of them turned against the government."},result:{immediate:"Phoenix reported more than 80,000 people removed, and spraying stripped more than 5 million acres of forest.",counterAction:"The guerrillas moved their bases across the borders and leaned more on regular troops from the North."},unintendedConsequence:"Both programs hurt America’s standing around the world. Agent Orange left health damage that Vietnamese families and American veterans still live with.",nextDecision:"How would these quiet campaigns hold up when the Tet Offensive hit the cities in 1968?"},interactiveModule:{id:"phoenix-analysis",type:"phoenix-analysis",title:"Phoenix and Ranch Hand in numbers",prompt:"Check the Phoenix Program’s official numbers, including what the word neutralized covered and why 87% of the deaths came from regular combat. Then see what Operation Ranch Hand left behind."},primaryDocuments:[t],nextQuestion:{question:"How did a battle Hanoi lost end a presidency?",framing:"In the 1968 Tet Offensive, communist forces were pushed out of every major city they attacked and lost more than 40,000 fighters. Two months later, Lyndon Johnson announced he would not run again."},citations:[o._["c6-1"],o._["c6-2"],o._["c6-3"]]},{id:"tet-offensive",number:7,timeframe:"1968",leadImageId:"hue-1968",galleryImageIds:["embassy-saigon-1968","hue-refugees-1968","cronkite-hue-1968","lbj-march-31-1968"],title:"The Tet Offensive",subtitle:"In January 1968, communist forces attacked more than 100 cities and towns across South Vietnam at once. Americans watched the fighting on the evening news.",summary:"During the Lunar New Year of 1968, more than 84,000 communist troops attacked over 100 cities and bases across South Vietnam at once. U.S. and South Vietnamese forces beat back the attacks and badly weakened the Viet Cong in the South. But the offensive wrecked the Johnson administration’s claim that the war was going well. After Tet, Americans stopped arguing about how to win and started arguing about how to leave.",isLandmark:!0,landmarkMoment:{bannerTitle:"The Tet Offensive and the credibility gap",dateline:"January 31, 1968",location:"Saigon, Hue, Khe Sanh, and 100+ Urban Centers",quote:"To say that we are closer to victory today is to believe, in the face of the evidence, the optimists who have been wrong in the past. To suggest we are on the edge of defeat is to yield to unreasonable pessimism. To say that we are mired in stalemate seems the only realistic, yet unsatisfactory, conclusion.",quoteCitationId:"Q014",quoteSpeaker:"Walter Cronkite",quoteContext:"CBS News Special Report: Who, What, When, Where, Why? (February 27, 1968)"},featuredDocument:{citationId:"Q014",kind:"Broadcast transcript",stamp:"CBS News, Feb. 27, 1968",header:[["Program","CBS News Special Report"],["Speaker","Walter Cronkite"],["Aired","February 27, 1968"]],note:"Cronkite closed his report from Vietnam with these words. A month later, President Johnson announced he would not run again."},whatHappened:{narrative:["In late 1967, North Vietnamese forces surrounded the Marine base at Khe Sanh, near the DMZ. Washington feared it could become an American Dien Bien Phu, and Westmoreland’s attention stayed fixed on it. Khe Sanh was partly a diversion. In the early hours of January 30–31, 1968, during a holiday truce for Tet, the lunar new year, communist forces attacked 36 of 44 provincial capitals, five major cities and dozens of military bases across South Vietnam.[^c7-1]","In Saigon, a 19-man Viet Cong commando unit blew a hole in the wall around the U.S. Embassy. All of the attackers were killed or captured within hours, but live television showed dead Americans on the embassy grounds. In Hue, two North Vietnamese army regiments seized the old walled Citadel. U.S. Marines and South Vietnamese troops spent 26 days retaking it room by room, and more than 80 percent of the city was destroyed. While they held Hue, communist officials executed between 2,800 and 3,000 people, including government workers, teachers, Catholics and foreigners.[^c7-3]","As a battle, Tet was a failure for Hanoi. The mass uprising its leaders expected, the *Tong Khoi Nghia*, never happened. The Viet Cong lost more than 40,000 experienced fighters, and from then on, soldiers drafted in the North did most of the fighting.[^c7-1] But in the United States, Tet shook the public’s belief that the war was being won. On February 27, 1968, CBS anchor Walter Cronkite told viewers the war was “mired in stalemate.”[^Q014] When the military asked for 206,000 more troops, Johnson’s senior civilian advisers, known as the Wise Men, told him to scale back.[^c7-2] On March 31, 1968, Johnson announced a partial halt to the bombing and said he would not run for reelection.[^c7-2]"],sections:[{date:"Late 1967 – January 1968",heading:"Khe Sanh, and then the cities"},{date:"January–February 1968",heading:"The embassy and Hue"},{date:"February–March 1968",heading:"Losing the argument at home"}],keyEvents:[{date:"Jan 21, 1968",title:"The siege of Khe Sanh begins",detail:"Two North Vietnamese divisions surround 6,000 Marines for a 77-day artillery battle."},{date:"Jan 30–31, 1968",title:"The Tet Offensive begins",detail:"Attacks hit cities across the country at once. Commandos break into the U.S. Embassy grounds in Saigon."},{date:"Jan 31 – March 2",title:"The Battle of Hue",detail:"26 days of street fighting retake Hue. Mass graves of executed civilians are found."},{date:"Feb 27, 1968",title:"Walter Cronkite’s broadcast",detail:"Cronkite gives his own view that the war is stuck in a stalemate, and many Americans agree."},{date:"March 16, 1968",title:"The My Lai massacre",detail:"U.S. soldiers murder more than 500 unarmed civilians in Son My village. It stays secret until late 1969."},{date:"March 31, 1968",title:"Johnson drops out",detail:"Johnson stops bombing north of the 20th parallel and quits the presidential race."}]},washington:{keyActors:["Lyndon B. Johnson","Clark Clifford","Gen. William Westmoreland","Walter Cronkite","Sen. Eugene McCarthy"],strategicObjective:"Make the cities safe again, defeat the offensive and calm voters shocked by the violence.",underlyingAssumptions:["The enemy had suffered huge losses, so Americans should see Tet as a win.","News coverage had turned a battlefield win into a defeat in people’s minds."],internalDebates:["Westmoreland and General Earle Wheeler asked for 206,000 more troops to strike while the enemy was weak, including bases in Laos and Cambodia.","Defense Secretary Clark Clifford called together the Wise Men, senior statesmen such as Dean Acheson. They told Johnson that Americans would not support what victory would take."],homeFrontConstraints:["The anti-war movement surged into mainstream electoral politics; Eugene McCarthy and Robert Kennedy challenged LBJ in primary elections.","Assassination of Martin Luther King Jr. in April 1968 ignited urban riots across more than 100 American cities."],primaryDocumentRef:"tet-politburo-directive"},hanoi:{keyActors:["Le Duan","General Vo Nguyen Giap","General Van Tien Dung","Tran Van Tra"],strategicObjective:"Break Saigon’s government with a general offensive and uprising, and force the United States out.",underlyingAssumptions:["People in South Vietnam’s cities hated Thieu’s government and would rise up once the attacks began.","South Vietnamese army units would mutiny, fall apart or switch sides."],internalDebates:["Le Duan overruled Giap, who had warned that attacking the cities would expose their forces.","Afterward, field commanders were blamed for the unrealistic plan, the heavy losses and the uprising that never came."],homeFrontConstraints:["Decimation of indigenous southern Viet Cong networks, forcing Hanoi to fill southern units almost entirely with northern conscripts for the remainder of the war."],primaryDocumentRef:"tet-politburo-directive"},causalChain:{decision:{actor:"Le Duan in Hanoi; Lyndon Johnson",action:"Hanoi attacked the cities during the Tet holiday truce. Afterward, Johnson stopped sending more troops and opened peace talks.",date:"January–March 1968"},assumption:{premise:"Hanoi expected the people of the cities to rise up. Washington expected its battlefield win to restore Americans’ faith in the war.",blindSpot:"City people in the South hid instead of joining a revolt. Americans decided their leaders had misled them about how close victory was."},result:{immediate:"The Viet Cong lost more than 40,000 fighters. Johnson’s presidency fell apart, and American escalation stopped.",counterAction:"Richard Nixon won the 1968 election promising peace with honor and troop withdrawals."},unintendedConsequence:"From then on, the war’s outcome depended less on battles in Vietnam than on politics in the United States.",nextDecision:"How would Nixon bring half a million troops home without seeming to abandon South Vietnam?"},interactiveModule:{id:"tet-offensive-map",type:"tet-offensive-map",title:"Tet 1968 on the map",prompt:"Find where the attacks hit, from Saigon to Hue to Khe Sanh. Then compare Hanoi’s plan with what happened and with Washington’s response."},primaryDocuments:[{id:"tet-politburo-directive",registryId:"Q009",isVerified:!1,transcriptionStatus:"unverified_paraphrase",title:"Hanoi Politburo Strategic Resolution on the General Offensive (Resolution 14)",authorOrSpeaker:"Party Central Committee & Military Commission",role:"Hanoi High Command (Le Duan)",side:"hanoi",date:"December 1967 (Adopted January 1968)",classification:"Strictly Confidential Military Directive",archiveSource:"Military History Institute of Vietnam, Hanoi (Lich Su Quan Doi Nhan Dan)",archiveId:"MHIV Documents Vol. 3, 1995 (Directive summary)",excerpt:"The December 1967 military directive formulated operational goals for the Tet Offensive, calling for synchronized assaults against southern urban administrative centers and military headquarters under the doctrinal assumption that urban populations would stage a general uprising that would dismantle the Saigon military and force American withdrawal.",historicalContext:"The operational doctrine for the 1968 Tet Offensive. Le Duan’s faction assumed the South Vietnamese urban population would enthusiastically rise against the Thieu government when urban centers were struck.",whyItMatters:"Demonstrates Hanoi’s flawed assumption: the anticipated urban uprising failed to materialize, and southern Viet Cong units suffered severe losses even while achieving an unintended psychological breakthrough in the U.S.",originalDocumentUrl:"https://www.kansaspress.ku.edu/9780700611751/"}],nextQuestion:{question:"What did Vietnamization mean in practice?",framing:"Richard Nixon promised to bring American troops home and hand the fighting to South Vietnam’s army. Historians still argue over whether he expected that army to survive."},citations:[o._["c7-1"],o._["c7-2"],o._["c7-3"]]},{id:"nixon-and-vietnamization",number:8,timeframe:"1969–1972",leadImageId:"nixon-cambodia-1970",galleryImageIds:["coretta-king-1969","midway-1969","huey-handover-1970","valtman-veterans-1971"],title:"Nixon and Vietnamization",subtitle:"Nixon brought American troops home over four years. Meanwhile he widened the war into Cambodia and Laos.",summary:"Richard Nixon won the presidency promising peace with honor. His plan, called Vietnamization, cut U.S. ground troops from 543,000 to under 25,000. South Vietnam’s army, the ARVN, took over the fighting. To cover the pullout, Nixon widened the war. He secretly bombed Cambodia, sent troops across the border, and opened talks with Moscow and Beijing. Two big battles, Lam Son 719 in Laos and the 1972 Easter Offensive, showed the same thing. The ARVN could not hold on the ground without U.S. air power.",whatHappened:{narrative:["When Richard Nixon took office in 1969, Americans wanted the casualties to stop. Under the Nixon Doctrine and a policy called Vietnamization, he began bringing American ground troops home. Their number fell from a peak of 543,000 in 1969 to 24,000 by late 1972.[^c8-1] Historians still argue about what Nixon was really after. Revisionist scholars say General Creighton Abrams’ One War plan to secure the countryside was actually working.[^c8-2] Critics say Nixon and Henry Kissinger mainly wanted a decent interval: enough time between the American exit and South Vietnam’s fall that the fall would not look like an American defeat.[^c8-1]","To hit communist supply bases across the border, Nixon started Operation Menu in March 1969. B-52s secretly carpet-bombed neutral Cambodia, and the raids were hidden from Congress with a second set of records. In April 1970, American and South Vietnamese troops openly invaded Cambodia. Protests broke out on campuses across the country. On May 4, Ohio National Guardsmen shot and killed four students at Kent State University, and ten days later students were shot and killed at Jackson State. Congress answered with the Cooper-Church Amendment, which banned U.S. ground troops and advisers from Cambodia and Laos. It was the first time Congress had limited where troops could go during a war against a president’s wishes.[^c8-1]","In February 1971, Operation Lam Son 719 put Vietnamization to the test. Three South Vietnamese divisions crossed into Laos along Route 9 to cut the Ho Chi Minh Trail, with no American ground troops or advisers going along. North Vietnam struck back with masses of tanks and heavy artillery. The South Vietnamese pullback became a panicked retreat, with soldiers clinging to the skids of helicopters.[^c8-3] Washington said the raid slowed supplies from the North for a year. But it showed how exposed South Vietnam’s army was without American troops beside it. In March 1972, Hanoi launched the Easter Offensive, a full-scale invasion with hundreds of Soviet-supplied tanks. South Vietnamese forces held key cities like An Loc and Quang Tri only because of massive American bombing in Operation Linebacker I and the mining of Haiphong harbor. The South’s army could hold with American airpower. Without it, it could not."],sections:[{date:"1969",heading:"Bringing the troops home"},{date:"1969–1970",heading:"Cambodia, Kent State and Congress"},{date:"1971–1972",heading:"Vietnamization is tested"}],keyEvents:[{date:"March 1969",title:"Operation Menu begins",detail:"Secret B-52 bombing in Cambodia, hidden with false flight records."},{date:"June 1969",title:"The first troops come home",detail:"Meeting Thieu on Midway Island, Nixon announces the withdrawal of 25,000 U.S. troops."},{date:"April 30, 1970",title:"Troops enter Cambodia",detail:"U.S. and ARVN ground forces cross into Cambodia to destroy communist bases."},{date:"May 4, 1970",title:"The Kent State shootings",detail:"Ohio National Guardsmen kill four student protesters. Hundreds of colleges close."},{date:"Feb–March 1971",title:"Lam Son 719 in Laos",detail:"North Vietnamese tanks rout the ARVN’s push into Laos, showing the limits of Vietnamization."},{date:"March–Oct 1972",title:"The Easter Offensive and Linebacker I",detail:"A huge North Vietnamese invasion is beaten back by the ARVN with heavy U.S. air support."}]},washington:{keyActors:["Richard M. Nixon","Henry Kissinger","Melvin Laird","Gen. Creighton Abrams","President Nguyen Van Thieu"],strategicObjective:"Bring American troops home, reach peace with honor and use new ties with China and the Soviet Union to protect South Vietnam.",underlyingAssumptions:["Historians disagree about whether Nixon and Kissinger thought South Vietnam’s army could survive alone, or only wanted a decent interval before it fell.","Nixon’s 1972 visit to Beijing and his deals with Moscow would lead both to press Hanoi toward a compromise."],internalDebates:["Defense Secretary Melvin Laird wanted fast troop withdrawals to calm the country and protect the army’s morale.","Nixon and Kissinger preferred heavy bombing to keep the upper hand in the secret talks in Paris."],homeFrontConstraints:["Epidemic disciplinary and morale issues among remaining U.S. troops: drug abuse, combat refusals, racial tensions, and fragging.","Publication of the Pentagon Papers by Daniel Ellsberg in June 1971, exposing decades of government deception regarding the war."],primaryDocumentRef:"mccarthy-hanoi-1968"},hanoi:{keyActors:["Le Duan","Le Duc Tho","General Vo Nguyen Giap","Pham Van Dong"],strategicObjective:"Survive the bombing, test South Vietnam’s army in big battles and keep North Vietnamese troops in the South.",underlyingAssumptions:["Once American ground troops left, opposition at home would stop Washington from coming back.","Over time, the military balance in the South would swing Hanoi’s way."],internalDebates:["North Vietnamese leaders were furious that Soviet and Chinese leaders hosted Nixon in 1972 while American bombs were falling on the North.","They argued over whether to launch a big tank offensive, which became the Easter Offensive, or save their forces for a longer war."],homeFrontConstraints:["Severe logistical bottlenecks caused by the mining of Haiphong Harbor and destruction of northern transport networks under Linebacker I."],primaryDocumentRef:"cia-memo-giap-thanh-1966"},causalChain:{decision:{actor:"Richard Nixon; Hanoi’s Politburo",action:"Nixon pulled out ground troops but bombed more heavily, including in Cambodia and Laos. In 1972 Hanoi invaded the South with tanks in the Easter Offensive.",date:"1969–1972"},assumption:{premise:"Washington believed South Vietnam’s army could hold with American air support. Hanoi believed that army would break under a full tank assault.",blindSpot:"South Vietnam came to depend on American air power it could not replace. Hanoi’s invasion lost huge numbers of men to B-52 strikes."},result:{immediate:"American deaths and draft calls fell while South Vietnamese losses rose. Both sides saw that the South could hold only with American planes overhead.",counterAction:"In October 1972, Henry Kissinger and Le Duc Tho reached a secret deal in Paris."},unintendedConsequence:"The secret bombing and the 1970 invasion destabilized Cambodia and helped the Khmer Rouge rise to power.",nextDecision:"What did each side give up to make a deal, and why did Thieu refuse to sign it?"},interactiveModule:{id:"vietnamization-tracker",type:"vietnamization-tracker",title:"Could South Vietnam fight alone?",prompt:"Follow U.S. troop numbers, South Vietnamese combat deaths and American bombing from 1968 to 1972. Then weigh the argument over the decent interval."},primaryDocuments:[a],nextQuestion:{question:"Did the Paris Peace Accords end the war?",framing:"In late 1972 Henry Kissinger announced that peace was near. South Vietnam’s President Thieu read the draft and called it a death sentence for his country."},citations:[o._["c8-1"],o._["c8-2"],o._["c8-3"]]},{id:"paris-peace-accords",number:9,timeframe:"1972–1973",leadImageId:"paris-signing-1973",galleryImageIds:["b52-linebacker-1972","paris-accords-text-1973","loc-ninh-exchange-1973","homecoming-1973","hoa-lo-prison-1973","nixon-thieu-1973","calc-ceasefire-poster-1973"],title:"The Paris Peace Accords",subtitle:"Kissinger negotiated in secret for years. The deal he signed in 1973 brought Americans home and let North Vietnamese troops stay in the South.",summary:"In October 1972, Henry Kissinger and Le Duc Tho secretly agreed on a draft deal. U.S. troops would leave, and North Vietnamese troops could stay where they were in the South. South Vietnam’s President Thieu rejected it, and Nixon ordered the 11-day Christmas Bombing of Hanoi, called Linebacker II. The treaty signed in January 1973 was essentially the same as the October draft. It ended direct American involvement and left the civil war unsettled.",isLandmark:!0,landmarkMoment:{bannerTitle:"The Paris Peace Accords",dateline:"January 27, 1973",location:"International Conference Center, Avenue Kléber, Paris",quote:"The diplomatic settlement permitted an estimated 150,000 to 200,000 North Vietnamese combat troops to remain in South Vietnam while concluding the total withdrawal of American combat forces.",quoteSpeaker:"Pierre Asselin",quoteContext:"Historical analysis based on A Bitter Peace (2002)"},featuredDocument:{citationId:"Q010",kind:"Agreement",stamp:"UN Treaty Series, Vol. 935",header:[["Title","Agreement on Ending the War and Restoring Peace in Viet-Nam"],["Article","1"],["Signed","Paris, January 27, 1973"]],note:"All four sides signed: the United States, North Vietnam, South Vietnam and the Viet Cong’s Provisional Revolutionary Government. The United States agreed to pull out completely within 60 days."},whatHappened:{narrative:["Starting in 1969, Henry Kissinger held secret talks in a house outside Paris with Le Duc Tho, a member of Hanoi’s ruling Politburo. For three years, the talks were stuck on two demands neither side would drop. Washington insisted that every North Vietnamese soldier leave the South. Hanoi insisted that South Vietnam’s president, Nguyen Van Thieu, be removed before any political deal.","In October 1972, both sides gave ground. Hanoi dropped its demand that Thieu go right away and agreed that he could stay in charge in Saigon. In return, the United States agreed that about 150,000 to 200,000 North Vietnamese combat troops could stay where they were inside South Vietnam.[^c9-1] A few weeks before the 1972 presidential election, Kissinger told reporters that peace was at hand.","When Thieu saw the draft, he rejected it outright. Letting North Vietnamese troops stay on South Vietnamese soil, he said, was a death sentence for his country. Kissinger went back to Paris with 69 changes Thieu wanted, and the talks broke down. From December 18 to 29, 1972, Nixon ordered Operation Linebacker II, known as the Christmas Bombing. More than 20,000 tons of bombs fell on Hanoi and Haiphong.[^c9-1] Historians argue about why. The administration said the bombing forced Hanoi back to the table, but the Paris Peace Accords signed on January 27, 1973, were almost the same as the October draft. Its main effect was on Thieu. The bombing, together with Nixon’s secret written promises to bomb again if Hanoi broke the ceasefire, pushed him into signing.[^c9-2] The last U.S. combat troops left by March 29, 1973, and 591 American prisoners of war came home.[^c9-3]"],sections:[{date:"1969–1972",heading:"Secret talks outside Paris"},{date:"October 1972",heading:"A draft deal"},{date:"December 1972 – March 1973",heading:"The Christmas Bombing and the final deal"}],keyEvents:[{date:"Oct 8, 1972",title:"A breakthrough in Paris",detail:"Hanoi drops its demand that Thieu go. The U.S. lets North Vietnamese troops stay in the South."},{date:"Oct 26, 1972",title:"Kissinger says peace is near",detail:"Days before the U.S. election, Kissinger tells reporters that peace is close."},{date:"Dec 13, 1972",title:"The talks break down",detail:"Hanoi rejects 69 changes demanded by Thieu and Washington, and the talks stop."},{date:"Dec 18–29, 1972",title:"The Christmas Bombing",detail:"Eleven days of all-out B-52 raids on Hanoi and Haiphong. Missiles shoot down 16 B-52s."},{date:"Jan 5, 1973",title:"Nixon’s secret letter to Thieu",detail:"Nixon promises to strike back quickly and hard if Hanoi breaks the peace agreement."},{date:"Jan 27, 1973",title:"The Paris Peace Accords are signed",detail:"All four sides sign. The U.S. agrees to pull out completely within 60 days."}]},washington:{keyActors:["Richard M. Nixon","Henry Kissinger","President Nguyen Van Thieu","Alexander Haig"],strategicObjective:"Get the American prisoners of war back, bring the last troops home and leave South Vietnam in a position it could defend.",underlyingAssumptions:["Historians disagree about whether Nixon thought his threat of more B-52 strikes would stop a future invasion, or knew Congress would never allow it.","Congress would keep sending South Vietnam the military and economic aid it needed."],internalDebates:["Thieu accused Kissinger of giving away South Vietnam’s independence by letting enemy troops stay in the South.","Nixon told Thieu that if he refused to sign, the United States would make its own deal with Hanoi and cut off all aid."],homeFrontConstraints:["The incoming 93rd Congress in January 1973 had decisive majorities prepared to legislate an immediate end to all war funding.","Watergate: the June 1972 break-in began metastasizing into a constitutional crisis that rapidly eroded Nixon’s executive authority."],primaryDocumentRef:"paris-accords-treaty-1973"},hanoi:{keyActors:["Le Duc Tho","Le Duan","Nguyen Duy Trinh","Pham Van Dong"],strategicObjective:"Get every American soldier out for good while keeping North Vietnamese troops inside South Vietnam.",underlyingAssumptions:["Once American forces left and opinion at home hardened, Washington would be unable to return to the war.","Over time, the military balance in the South would swing Hanoi’s way."],internalDebates:["Hanoi rode out Linebacker II. Its leaders bet that shooting down B-52s and waiting out American patience would protect what they had won at the table."],homeFrontConstraints:["Severe devastation of urban infrastructure and rail lines from the Christmas bombing; air defense missile stockpiles were near total exhaustion by December 29."],primaryDocumentRef:"paris-accords-treaty-1973"},causalChain:{decision:{actor:"Nixon, Kissinger and Le Duc Tho",action:"They signed the Paris Peace Accords. All American forces left, and about 150,000 North Vietnamese troops stayed in the South.",date:"January 27, 1973"},assumption:{premise:"The threat of American air power would keep Hanoi from breaking the deal.",blindSpot:"That threat rested on Nixon’s personal promises, and Watergate soon wrecked his power to keep them."},result:{immediate:"591 American prisoners of war came home, and the last U.S. combat troops left on March 29, 1973.",counterAction:"North and South Vietnam kept fighting over contested villages, a struggle called the war of the flags."},unintendedConsequence:"America’s part in the war ended. Vietnam’s war went on, and South Vietnam was left exposed.",nextDecision:"Once Congress banned any return of American forces, what would stop Hanoi’s final offensive?"},interactiveModule:{id:"paris-timeline",type:"paris-timeline",title:"How the Paris deal was made",prompt:"Follow the secret talks to October 1972, when each side gave ground. Then see why Thieu objected and what historians say the Christmas Bombing was for."},primaryDocuments:[n],nextQuestion:{question:"Why did South Vietnam’s army fall apart in 55 days?",framing:"In early 1975, South Vietnam’s army looked strong on paper. Then aid ran short, fuel was rationed and Thieu ordered a retreat that turned into a rout."},citations:[o._["c9-1"],o._["c9-2"],o._["c9-3"]]},{id:"the-collapse",number:10,timeframe:"1973–1975",leadImageId:"frequent-wind-1975",galleryImageIds:["ford-nsc-1975","babylift-ford-1975","kissinger-evacuation-1975","tan-son-nhut-evacuation-1975","hancock-pilots-1975","hancock-girl-1975"],title:"The fall of Saigon",subtitle:"In the spring of 1975, North Vietnam’s army took the South in 55 days. On April 30, its tanks rolled through the gates of the Presidential Palace in Saigon.",summary:"After the U.S. left, South Vietnam’s economy shrank, prices soared, and Congress cut aid so sharply that the army had to ration ammunition and fuel. In June 1973, Congress passed the Case-Church Amendment, which made it illegal for U.S. forces to go back in. In late 1974, Hanoi tested America’s will at Phuoc Long. No response came, so it sped up its campaign. President Thieu’s sudden order to retreat from the Central Highlands turned into a rout. South Vietnam fell in 55 days, and Saigon was captured on April 30, 1975.",isLandmark:!0,landmarkMoment:{bannerTitle:"The 55 days that ended South Vietnam",dateline:"April 30, 1975, 11:30 a.m.",location:"The Independence Palace, Saigon",quote:"On the morning of April 30, 1975, North Vietnamese armored units breached the perimeter gates of Saigon’s Presidential Palace, concluding the military collapse of the Republic of Vietnam.",quoteSpeaker:"George J. Veith",quoteContext:"Historical account based on Black April (2012)"},whatHappened:{narrative:["In 1973 and 1974, South Vietnam’s economy shrank sharply as American military spending disappeared. Congress, tired of the corruption in Saigon and set on getting out, cut military aid from $2.3 billion to less than $700 million.[^c10-1] South Vietnamese units had to ration artillery shells and bullets, and helicopters sat on the ground for lack of spare parts. In June 1973, Congress passed the Case-Church Amendment by margins large enough to override a veto. It banned all U.S. military action in Indochina after August 15, 1973, so Nixon’s private promises of air support to Thieu could no longer be kept.[^c10-1] In August 1974, Nixon resigned over the Watergate scandal. President Gerald Ford had neither the legal power nor the political support to step in.","In December 1974, communist forces attacked Phuoc Long province, about 60 to 75 miles north of Saigon, to test whether the United States would start bombing again. Congress turned down Ford’s requests for emergency aid, and no air strikes came. Hanoi concluded that the Americans would not come back. General Van Tien Dung planned a two-year campaign for 1975 and 1976. On March 10, 1975, North Vietnamese tanks made a surprise attack and captured Ban Me Thuot in the Central Highlands.[^c10-2] On March 14, Thieu panicked and ordered his army to abandon the whole Central Highlands so it could defend a smaller area around Saigon.[^c10-1]","The disorganized retreat down Route 7B, an unpaved road, became known as the Column of Tears. More than 200,000 soldiers and 400,000 civilian refugees were shelled along the way, and soldiers left their posts to save their families.[^c10-3] Hue fell on March 25. Da Nang collapsed into chaos on March 30, with 300,000 refugees crowding the city. After the war, many people believed that South Vietnamese troops simply refused to fight. That is not the whole story. At Xuan Loc, the ARVN 18th Division under Brigadier General Le Minh Dao held out from April 9 to 21 and inflicted heavy losses on three North Vietnamese divisions before it was outflanked.[^c10-1] Hanoi sped up its timetable and renamed the push the Ho Chi Minh Campaign. At 11:30 a.m. on April 30, 1975, North Vietnamese tanks crashed through the gates of the Presidential Palace in Saigon.[^c10-2]"],sections:[{date:"1973–1974",heading:"The aid runs out"},{date:"December 1974 – March 1975",heading:"Hanoi tests Washington"},{date:"March–April 1975",heading:"Fifty-five days"}],keyEvents:[{date:"June 1973",title:"Congress bans further fighting",detail:"The Case-Church Amendment bans U.S. military action in Indochina after August 15, 1973."},{date:"Nov 7, 1973",title:"The War Powers Act passes",detail:"Congress overrides Nixon’s veto and limits the president’s power to send troops abroad."},{date:"Aug 9, 1974",title:"Nixon resigns",detail:"Gerald Ford becomes president. South Vietnam loses the man who made it promises."},{date:"Dec 1974 – Jan 1975",title:"Phuoc Long: Hanoi tests the U.S.",detail:"Communist forces take a province to test the U.S. No American planes come."},{date:"March 10–12, 1975",title:"Ban Me Thuot falls",detail:"North Vietnamese tanks take this key town in the Central Highlands. Thieu orders a badly planned retreat."},{date:"April 9–21, 1975",title:"The Battle of Xuan Loc",detail:"The ARVN 18th Division holds for two weeks, 40 miles from Saigon, before pulling back."},{date:"April 30, 1975",title:"Saigon falls",detail:"Operation Frequent Wind flies out the last Americans. North Vietnamese tanks enter the Presidential Palace."}]},washington:{keyActors:["Gerald R. Ford","Henry Kissinger","Graham Martin (Ambassador to Saigon)"],strategicObjective:"Win emergency aid from Congress to steady South Vietnam, get Americans out safely and limit the damage of defeat.",underlyingAssumptions:["Even if South Vietnam was weakening, Washington expected it to hold out against major attacks until at least 1976.","Ambassador Graham Martin put off evacuation plans because he feared they would set off panic and speed the collapse."],internalDebates:["President Ford asked Congress for $722 million in emergency military aid. Congressional leaders turned him down, treating the war as finished."],homeFrontConstraints:["The American public and Congress were entirely unwilling to risk further casualties or expend additional funds in Southeast Asia."],primaryDocumentRef:"paris-accords-treaty-1973"},hanoi:{keyActors:["Le Duan","General Van Tien Dung","Vo Nguyen Giap","Pham Hung"],strategicObjective:"Take the whole South, defeat South Vietnam’s army and force Saigon to surrender without conditions.",underlyingAssumptions:["At first Hanoi planned a two-year campaign for 1975 and 1976, expecting South Vietnam’s army to fight hard.","The collapse came so fast that it surprised even General Dung, who ordered his commanders to move faster and take bigger risks."],internalDebates:["After Ban Me Thuot fell, commanders debated whether to pause and bring up supplies, or send every reserve unit down Route 1 at once."],homeFrontConstraints:["Extremely stretched logistical lines racing hundreds of trucks, tanks, and fuel pipelines south over hundreds of miles of captured highway."],primaryDocumentRef:"paris-accords-treaty-1973"},causalChain:{decision:{actor:"Congress; President Thieu; General Van Tien Dung",action:"Congress cut aid and barred any return of American air power. Thieu ordered the retreat from the Central Highlands, and Hanoi sped up its attack.",date:"1973–1975"},assumption:{premise:"Thieu thought his army could pull back in good order and defend a smaller area. Congress thought cutting aid would push Saigon toward a political deal.",blindSpot:"An army retreating under fire, with soldiers’ families on the same roads, broke into a rout. The aid cuts had already left units short of fuel and ammunition."},result:{immediate:"South Vietnam fell in 55 days. The end came on April 30, 1975.",counterAction:"General Duong Van Minh, president for two days, announced South Vietnam’s unconditional surrender."},unintendedConsequence:"The war ended in total defeat for the South, and hundreds of thousands of people soon fled the country.",nextDecision:"What happened to the people of Vietnam after reunification?"},interactiveModule:{id:"collapse-1975-map",type:"collapse-1975-map",title:"The 55-day collapse",prompt:"Step through the collapse, from the break at Ban Me Thuot to Thieu’s retreat order and the panic at Da Nang. Finish with the last stand at Xuan Loc."},primaryDocuments:[n],nextQuestion:{question:"What did peace look like in Vietnam after 1975?",framing:"The shooting stopped, but Vietnam did not settle down. Re-education camps and new wars with Cambodia and China followed, and more than a million people fled by sea."},citations:[o._["c10-1"],o._["c10-2"],o._["c10-3"]]},{id:"aftermath-1975",number:11,timeframe:"1975–1995",leadImageId:"vietnam-memorial-wall",galleryImageIds:["boat-people-1984","camp-pendleton-1975","indiantown-gap-1975","cargo-net-rescue-1979"],title:"After the war",subtitle:"After 1975 came re-education camps, the boat people and new wars. Relations with the United States did not return to normal until 1995.",summary:"The fall of Saigon reunited Vietnam but did not bring peace right away. The years after the war brought a stalled economy, forced collective farming, re-education camps, and new wars with Cambodia and China. More than one million boat people fled, many of them ethnic Chinese who were being targeted. Near-famine and runaway inflation finally pushed the Communist Party to open up the economy with the Doi Moi reforms of 1986.",whatHappened:{narrative:["After the victory, Hanoi formally reunited the country in July 1976 as the Socialist Republic of Vietnam. The new government ran the economy from the top. It took over private businesses in the South and forced farmers in the Mekong Delta onto collective farms. With a U.S. trade embargo, the loss of Western aid and poor management on top of that, farm output collapsed. By the late 1970s there was rationing and near-famine, and in 1986 inflation rose above 700 percent.","The new government also locked up its former enemies. Hundreds of thousands of former South Vietnamese military officers, government workers and religious leaders were sent to re-education camps, *trai cai tao* in Vietnamese. They had been told to expect a few political lectures. Instead, officers and senior officials were held for 3 to more than 10 years of forced labor and political lessons. At the same time, the New Economic Zones program forced about 750,000 to more than 1 million people from southern cities onto undeveloped land in the jungle, while about 1 million northerners moved south.","Between 1975 and 1995, somewhere between 800,000 and nearly 2 million refugees fled Indochina by sea. The crisis peaked in 1978–1979, as relations with China broke down. Vietnam’s government turned on its ethnic Chinese citizens, the Hoa. It seized their property and drove hundreds of thousands of them into boats on the South China Sea, and in some months the Hoa made up 50 to 80 percent of new arrivals at refugee camps. International agencies estimate that 200,000 to 500,000 people died at sea from drowning, exposure and pirate attacks. The region did not find peace either. In December 1978, Vietnam invaded Cambodia and overthrew the Khmer Rouge, which had committed genocide there. In February 1979, China invaded northern Vietnam to punish it. With its economy failing, Vietnam’s Communist Party adopted *Doi Moi*, or Renovation, at its 6th Congress in December 1986. It ended collective farming and moved the country toward a market economy."],sections:[{date:"1975–1986",heading:"A planned economy fails"},{date:"1975–1980s",heading:"Camps and forced moves"},{date:"1975–1995",heading:"The boat people and new wars"}],keyEvents:[{date:"1975–1985",title:"Re-education camps and collective farms",detail:"More than 1 million people go through the camps. Southern farms are forced into collectives, and food runs short."},{date:"July 2, 1976",title:"Vietnam is officially reunited",detail:"North and South become one country. Saigon is renamed Ho Chi Minh City."},{date:"Nov 1978",title:"The Hai Hong",detail:"Malaysia turns away a ship carrying 2,500 refugees. The UN refugee agency starts treating boat people as refugees as a group."},{date:"Dec 1978 – Jan 1979",title:"Vietnam invades Cambodia",detail:"Vietnamese forces overthrow Pol Pot’s Khmer Rouge and then fight guerrillas there for ten years."},{date:"Feb–March 1979",title:"China and Vietnam go to war",detail:"China invades northern Vietnam to punish it. Both sides lose many soldiers."},{date:"Dec 1986",title:"Doi Moi reforms begin",detail:"The 6th Party Congress drops central planning and collective farms and adopts market reforms."}]},washington:{keyActors:["Gerald Ford","Jimmy Carter","Ronald Reagan","United Nations High Commissioner for Refugees"],strategicObjective:"Take in refugees, keep the trade embargo on Vietnam, account for Americans missing in action and help Vietnam’s neighbors push it out of Cambodia.",underlyingAssumptions:["Cutting Vietnam off from trade and diplomacy would force Hanoi out of Cambodia and make it act more cautiously."],internalDebates:["Talks about restoring relations stalled in the late 1970s, after Vietnam invaded Cambodia and gave the Soviet navy use of Cam Ranh Bay."],homeFrontConstraints:["The Vietnam Syndrome: deep public and congressional aversion to overseas military intervention.","Resettlement of hundreds of thousands of Vietnamese, Hmong, and Cambodian refugees across American communities."],primaryDocumentRef:"ap-casualty-disclosure-1995"},hanoi:{keyActors:["Le Duan","Nguyen Van Linh","Truong Chinh","Vo Van Kiet"],strategicObjective:"Bring socialism to the South, crush opponents, defend the borders with Cambodia and China and fix a failing economy.",underlyingAssumptions:["Leaders thought the North’s planned economy could be imposed on the South’s market economy by decree.","Historians disagree about what pushed Vietnam toward Doi Moi: the Western embargo, or collapse at home, runaway inflation and shrinking Soviet aid."],internalDebates:["Hardliners feared that markets would water down the party’s ideas. Southern reformers such as Vo Van Kiet and Nguyen Van Linh showed that private markets and family farms were needed to keep people fed."],homeFrontConstraints:["Severe inflation reaching 700% in 1986, near-famine in rural provinces, and heavy military casualties in Cambodia and along the Chinese border."],primaryDocumentRef:"ap-casualty-disclosure-1995"},causalChain:{decision:{actor:"Vietnam’s Communist Party",action:"The party forced farmers onto collectives, sent former enemies to re-education camps and invaded Cambodia. In 1986 it changed course with Doi Moi.",date:"1975–1986"},assumption:{premise:"Leaders thought victory would let them build a modern socialist economy quickly, and that their army could settle border fights.",blindSpot:"Collective farming wrecked food production. The wars and the refugee crisis left Vietnam isolated."},result:{immediate:"Vietnam faced near-famine, more than a million people fled, and most of the world kept its distance.",counterAction:"Doi Moi in 1986 ended collective farming and made private business legal again."},unintendedConsequence:"To stay in power, the party gave up the economic system it had fought thirty years to build.",nextDecision:"How do historians, veterans and ordinary people make sense of the war today?"},interactiveModule:{id:"aftermath-metrics",type:"aftermath-metrics",title:"What the war cost",prompt:"Look at the casualty estimates from Vietnam’s 1995 disclosure and at the two waves of refugees, including the ethnic Chinese families who fled. Then read what is known about the re-education camps."},primaryDocuments:[i],nextQuestion:{question:"Why do people still argue about the Vietnam War?",framing:"Some historians say the war could never have been won. Others say politics at home threw away a war the United States could have won, and a newer group looks at the choices every side made."},citations:[{id:"c11-1",marker:1,citation:"Robinson, W. Courtland. Terms of Refuge: The Indochinese Exodus and the International Response. Zed Books, 1998.",sourceType:"academic-monograph"},{id:"c11-2",marker:2,citation:"Hirschman, Charles, et al. “Vietnamese Casualties During the American War: A New Estimate.” Population and Development Review, 1995.",sourceType:"academic-monograph"},{id:"c11-3",marker:3,citation:"Evans, Grant, and Kelvin Rowley. Red Brotherhood at War: Vietnam, Cambodia and Laos since 1975. Verso, 1990.",sourceType:"academic-monograph"}]},{id:"memory-and-the-argument",number:12,timeframe:"1975 to today",leadImageId:"mcnamara-map-1965",galleryImageIds:["memorial-dedication-1982","reagan-wall-1988","remembering-vietnam-exhibit-2017"],title:"How historians argue about the war",subtitle:"Was the war unwinnable, or lost at home? Four groups of historians answer differently, using different evidence.",summary:"Fifty years after the war ended, historians and citizens still argue about why it happened, how it was fought, and what it means. There are four main schools of thought: Orthodox, Revisionist, Post-Revisionist, and one built on Vietnamese archives. Learning them shows how the same evidence can be read in different ways, and why no single account of the war is accepted by everyone.",whatHappened:{narrative:["World War II left most Americans agreed on why it was fought and that it was right. Vietnam left them divided, and historians still disagree about it. Their arguments come from reading the same documents in different ways, from different views of what each army could do, and from different answers to one question: did the government in Saigon have its people’s support?","The Orthodox school, also called the liberal realist school, includes David Halberstam, Arthur Schlesinger Jr. and George Herring. These historians see the war as a quagmire that could never be won. In their view, American leaders were blinded by a rigid belief in containing communism. They mistook a real nationalist revolution against colonial rule for part of a single Soviet and Chinese plot. Because South Vietnam’s government never won the loyalty of its own people, no amount of American military power could build a lasting non-communist state.","The Revisionist school, also called the conservative school, includes Guenter Lewy, Harry Summers and Lewis Sorley. These historians argue that defending South Vietnam from communist attack was a noble cause, and that the war could have been won. They say General Creighton Abrams’ One War strategy had made the countryside largely secure after 1968. In their view, South Vietnam fell in 1975 because Congress cut aid, the press was biased and the United States walked away, and not because its army was beaten.","In the past twenty years, archives in Vietnam, the former Soviet Union and China have opened. That has produced a Post-Revisionist or international school, including Fredrik Logevall, Lien-Hang Nguyen and Pierre Asselin. These historians move past the question of whether the war was winnable. They treat the Vietnamese on every side as people who made their own choices and played their big-power backers against each other. Their work shows Hanoi under Le Duan as a hard-line government that crushed moderates at home, and it gives South Vietnamese society back its own voice. Vietnamese writers have challenged the official heroic story too, among them the North Vietnamese veterans Bao Ninh, author of *The Sorrow of War*, and Duong Thu Huong. Even the war museum in Ho Chi Minh City has changed its name three times, from *Exhibition House for US and Puppet Crimes* to *War Crimes Museum* to *War Remnants Museum*, as relations with the United States returned to normal in 1995."],sections:[{heading:"Why historians still disagree"},{heading:"The Orthodox school"},{heading:"The Revisionist school"},{date:"Since the 1990s",heading:"The Post-Revisionist school"}],keyEvents:[{date:"1972",title:"Halberstam publishes The Best and the Brightest",detail:"A founding orthodox book about how smart, confident officials led the country into war."},{date:"1981",title:"Summers publishes On Strategy",detail:"A revisionist book arguing the military should have focused on blocking invasion routes from the North."},{date:"1990",title:"Bao Ninh publishes The Sorrow of War",detail:"A North Vietnamese veteran’s novel shows the war as grief and trauma, not the heroic story the state told."},{date:"1995",title:"The U.S. and Vietnam restore relations",detail:"President Bill Clinton and Prime Minister Vo Van Kiet restore full relations between the two countries."},{date:"2012",title:"Lien-Hang Nguyen publishes Hanoi’s War",detail:"A study based on Vietnamese records of Le Duan’s police state, his purges and his wartime diplomacy."}]},washington:{keyActors:["Historians, Veterans, & Citizens: Realists vs Revisionists vs Internationalists"],strategicObjective:"Learn from the war in ways that guide how the United States uses force today.",underlyingAssumptions:["Orthodox historians: military power cannot make up for a government its own people will not support.","Revisionist historians: politicians tied the military’s hands and kept it from winning."],internalDebates:["Would Kennedy have pulled out of Vietnam if he had lived past 1963?","Did Nixon plan the decent interval on purpose, or is that an idea critics came up with later?"],homeFrontConstraints:["The cultural legacy: how the memory of Vietnam shaped American public debates over military interventions in the Persian Gulf, the Balkans, Afghanistan, and Iraq."],primaryDocumentRef:"ap-casualty-disclosure-1995"},hanoi:{keyActors:["Official State Historians vs Independent Researchers & Diaspora Voices"],strategicObjective:"Square the party’s official story of a great patriotic victory with what the archives and the refugees have to say.",underlyingAssumptions:["The party’s official history calls victory the certain result of Marxism-Leninism and national unity under the Communist Party.","Scholars working from archives and from refugee accounts stress the huge human cost, repression inside the North and South Vietnam’s separate, non-communist identity."],internalDebates:["Some topics are still sensitive in Vietnam today, among them the killings of civilians at Hue in 1968, the 1979 war with China and conditions in the re-education camps."],homeFrontConstraints:["Generational transition: a youthful population focused on economic development and global integration rather than wartime ideology."],primaryDocumentRef:"ap-casualty-disclosure-1995"},causalChain:{decision:{actor:"Congress and later presidents",action:"Congress passed the War Powers Act in 1973, and American leaders grew wary of long wars abroad.",date:"1973–1991"},assumption:{premise:"Limits on presidential power and a cautious public would keep the country out of another Vietnam.",blindSpot:"One war’s lessons do not fit every war, and leaders argued for decades over what Vietnam had taught."},result:{immediate:"For almost twenty years, the United States avoided large ground wars abroad.",counterAction:"In 1984 Defense Secretary Caspar Weinberger set out conditions for using force, and Colin Powell later built on them."},unintendedConsequence:"After the 1991 Gulf War, President George H.W. Bush declared that the country had put the Vietnam Syndrome behind it. The argument over Vietnam’s lessons came back with the wars after 9/11.",nextDecision:"Which lesson of Vietnam holds up best, and what evidence would you use to prove it?"},interactiveModule:{id:"competing-arguments",type:"competing-arguments",title:"Four schools of thought",prompt:"Compare the four schools: what each one claims, the evidence it leans on and how other historians push back."},primaryDocuments:[i],nextQuestion:{question:"What would you have decided?",framing:"You have followed thirty years of decisions. Pick a turning point, read its documents again and test your answer in the study guide."},citations:[{id:"c12-1",marker:1,citation:"Halberstam, David. The Best and the Brightest. Random House, 1972.",sourceType:"academic-monograph"},{id:"c12-2",marker:2,citation:"Summers, Harry G. On Strategy: A Critical Analysis of the Vietnam War. Presidio Press, 1982.",sourceType:"academic-monograph"},{id:"c12-3",marker:3,citation:"Logevall, Fredrik. Choosing War: The Lost Chance for Peace and the Escalation of War in Vietnam. University of California Press, 1999.",sourceType:"academic-monograph"},{id:"c12-4",marker:4,citation:"Nguyen, Lien-Hang T. Hanoi’s War: An International History of the War for Peace in Vietnam. University of North Carolina Press, 2012.",sourceType:"academic-monograph"}]}].sort((e,t)=>e.number-t.number);r.length;let s=[{title:"Getting in",years:"1945–1963",firstChapter:1},{title:"The American war",years:"1964–1968",firstChapter:4},{title:"Getting out",years:"1969–1975",firstChapter:8},{title:"Afterward",years:"1975 to today",firstChapter:11}],d=s.map((e,t)=>{let a=s[t+1]?.firstChapter??1/0;return{number:t+1,title:e.title,years:e.years,chapters:r.filter(t=>t.number>=e.firstChapter&&t.number<a)}});e.s(["s",0,d,"L",0,r,"u",0,function(e){return{prev:r.find(t=>t.number===e.number-1),next:r.find(t=>t.number===e.number+1)}},"w",0,function(e){return d.find(t=>t.chapters.some(t=>t.id===e.id))}],66133)}]);